/* Vragenbank PA-toets, Wft Basis. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["basis"] = [
["Welk toezichtmodel hanteert Nederland voor de financiële sector?", [["Twin peaks: de AFM houdt gedragstoezicht en DNB prudentieel toezicht", "Het toezicht is ingedeeld naar doel: de AFM let op het gedrag richting klanten en markten, DNB op de soliditeit van instellingen."], ["Een sectoraal model met één toezichthouder per branche", "Dat model is juist verlaten; het toezicht is ingedeeld naar doel en niet naar sector zoals banken of verzekeraars."], ["Eén centrale toezichthouder voor de hele sector, namelijk DNB", "Nederland kent twee toezichthouders met elk een eigen taak; DNB houdt geen gedragstoezicht op adviseurs."], ["Toezicht door het ministerie van Financiën, met de AFM en DNB als adviseurs", "Het ministerie maakt beleid en wetgeving; het toezicht zelf is belegd bij AFM en DNB."]], "1f.13"],
["Fatima Ouali (68) is net met pensioen. Haar AOW en pensioen samen zijn lager dan haar vaste lasten en overige uitgaven. Daarom haalt zij elke maand € 300,00 van haar spaarrekening om het tekort aan te vullen. Haar kleinzoon noemt dat sparen in omgekeerde richting. Hoe heet wat Fatima doet?", [["Ontsparen", "Bij ontsparen wordt eerder opgebouwd vermogen gebruikt om uitgaven te betalen die hoger zijn dan het inkomen."], ["Lenen", "Bij lenen gebruik je geld van een ander dat je moet terugbetalen; Fatima gebruikt haar eigen spaargeld."], ["Beleggen", "Bij beleggen zet je vermogen in om rendement te halen; Fatima neemt juist vermogen op."], ["Investeren", "Investeren is geld besteden aan productiemiddelen, zoals een machine voor een bedrijf."]], "1a.1"],
["Wat is volgens de Wft het doel van het gedragstoezicht door de AFM?", [["Ordelijke en transparante marktprocessen, zuivere verhoudingen tussen marktpartijen en zorgvuldige behandeling van cliënten", "Dit is de wettelijke omschrijving van het gedragstoezicht; de nadruk ligt op het gedrag van partijen, ook richting klanten."], ["De financiële soliditeit van banken, verzekeraars en pensioenfondsen waarborgen, zodat zij hun verplichtingen kunnen nakomen", "Dat is het doel van prudentieel toezicht, de taak van DNB en niet van de AFM."], ["De stabiliteit van het financiële stelsel als geheel bewaken en crises voorkomen", "Financiële stabiliteit hoort bij de taken van DNB; de AFM richt zich op gedrag en transparantie."], ["Individuele geschillen tussen consumenten en financiële dienstverleners bindend beslechten en daarbij schadevergoedingen toekennen", "Geschillen worden beslecht door Kifid of de rechter; de AFM is geen geschilleninstantie."]], "1f.14"],
["Peter de Vries (52) heeft via een adviseur een arbeidsongeschiktheidsverzekering afgesloten. Bij zijn eerste claim blijkt de dekking smaller dan hij had begrepen. Hij belt boos de AFM en verwacht dat de AFM de adviseur dwingt hem schadeloos te stellen. Hij vraagt jou of dat de juiste weg is. Wat leg je Peter uit?", [["De AFM beslecht geen individuele geschillen; Peter dient zijn klacht in bij de adviseur en kan daarna naar Kifid", "De AFM gebruikt meldingen als signaal voor haar toezicht, maar kent geen schadevergoeding toe. Voor een individueel geschil zijn de interne klachtenprocedure en daarna Kifid of de rechter bedoeld."], ["De AFM onderzoekt de klacht, hoort beide partijen en kent bij een gegronde klacht een schadevergoeding toe", "De AFM is toezichthouder en geen geschilleninstantie; een schadevergoeding loopt via Kifid of de rechter."], ["De AFM stuurt de klacht door naar DNB, omdat DNB klachten over verzekeringen behandelt", "DNB houdt prudentieel toezicht en behandelt evenmin individuele klachten van consumenten."], ["De AFM verplicht de adviseur om binnen vier weken een schikking met Peter te treffen", "De AFM kan in een individueel geschil geen schikking afdwingen; dat hoort bij Kifid of de rechter."]], "1f.5"],
["Welke maatregel kan de AFM zelf opleggen aan een financiële onderneming die de Wft overtreedt?", [["Een bestuurlijke boete of een last onder dwangsom", "Dit zijn bestuursrechtelijke handhavingsinstrumenten die de Wft aan de AFM toekent; daarnaast kan zij onder meer een aanwijzing geven of de vergunning intrekken."], ["Een gevangenisstraf voor de verantwoordelijke bestuurders", "Vrijheidsstraffen kan alleen de strafrechter opleggen, niet een toezichthouder."], ["Een schadevergoeding aan de gedupeerde klanten van de onderneming", "Het toekennen van schadevergoeding is voorbehouden aan de rechter of een geschilleninstantie zoals Kifid."], ["Het faillissement van de onderneming, uitgesproken door de AFM zelf", "Een faillissement wordt door de rechtbank uitgesproken; de AFM kan dat niet zelf doen."]], "1f.17"],
["Hoe kan een consument het beste nagaan of een financieel adviseur over een Wft-vergunning beschikt?", [["Door het openbare register van de AFM te raadplegen", "De AFM verleent de vergunningen voor adviseren en bemiddelen en houdt daarvan een openbaar register bij."], ["Door het handelsregister van de Kamer van Koophandel te raadplegen", "Een KvK-inschrijving zegt niets over het hebben van een Wft-vergunning; elk bedrijf moet zich daar inschrijven."], ["Door bij het BKR een vergunningcheck aan te vragen", "Het BKR registreert kredieten van consumenten en houdt geen register van vergunningen bij."], ["Door bij DNB te controleren of het kantoor solvabel is", "DNB verleent geen vergunningen aan adviseurs en bemiddelaars; dat doet de AFM."]], "1f.25"],
["Aan wie verleent de AFM een vergunning voor het adviseren over of bemiddelen in financiële producten?", [["Aan de financiële onderneming", "De vergunning geldt voor de onderneming; individuele medewerkers moeten daarnaast zelf vakbekwaam zijn."], ["Aan iedere individuele adviseur persoonlijk", "Medewerkers hebben geen eigen vergunning nodig; voor hen gelden de vakbekwaamheidseisen."], ["Aan de branchevereniging namens haar leden", "Een branchevereniging kan geen vergunning namens leden houden; elke onderneming vraagt die zelf aan."], ["Aan de aanbieder, die daarmee al zijn tussenpersonen dekt", "De vergunning van een bank of verzekeraar dekt in beginsel niet de activiteiten van zelfstandige tussenpersonen."]], "1f.25"],
["Voor welke activiteit is in beginsel een Wft-vergunning van de AFM nodig?", [["Adviseren over een overlijdensrisicoverzekering", "Een overlijdensrisicoverzekering is een financieel product in de zin van de Wft; adviseren erover is vergunningplichtig."], ["Bemiddelen bij de aankoop van een woning als makelaar", "Makelaardij in onroerend goed is geen dienstverlening over een financieel product in de zin van de Wft."], ["Het opstellen van een testament voor een klant", "Een testament is een notariële akte en geen financieel product; daarvoor geldt geen Wft-vergunning."], ["Het verzorgen van de jaarlijkse belastingaangifte", "Belastingadvies en aangiftewerk vallen niet onder de Wft-vergunningplicht."]], "1f.25"],
["Wat verstaat de Wft in de kern onder bemiddelen?", [["Werkzaamheden gericht op het sluiten van een overeenkomst over een financieel product tussen klant en aanbieder", "Bemiddelen draait om het tot stand brengen van de overeenkomst; bij verzekeringen hoort ook het assisteren bij beheer en uitvoering ervan."], ["Het doen van een persoonlijke aanbeveling aan een klant over een of meer specifieke financiële producten van een aanbieder", "Dat is de omschrijving van adviseren; adviseren en bemiddelen zijn afzonderlijke activiteiten."], ["Het zelf als wederpartij aangaan van de overeenkomst met de klant", "Wie zelf de wederpartij is, biedt het product aan; dat is aanbieden en geen bemiddelen."], ["Het namens de klant beheren van diens vermogen naar eigen inzicht", "Dat is vermogensbeheer, een beleggingsdienst met een eigen regime."]], "1f.29"],
["Een website legt in algemene termen uit wat het verschil is tussen een annuïteiten- en een lineaire hypotheek, zonder gegevens van de bezoeker te vragen. Is dit adviseren in de zin van de Wft?", [["Nee, algemene informatie zonder op de persoon toegesneden aanbeveling is geen advies", "Zonder persoonlijke aanbeveling over een specifiek product is er sprake van informatieverstrekking, die wel correct en niet misleidend moet zijn."], ["Ja, alle informatie over financiële producten geldt als advies", "Niet alle informatie is advies; het gaat om een persoonlijke aanbeveling over een specifiek product."], ["Ja, want informatie over hypotheken is altijd vergunningplichtig advies, ook zonder klantgegevens", "Ook over hypotheken mag algemene voorlichting worden gegeven zonder dat sprake is van advies."], ["Nee, want informatie op een website valt nooit onder de Wft", "Ook online kan advies worden gegeven, en ook voor websites gelden de informatieregels van de Wft."]], "1f.19"],
["Ronald Bakker heeft een fietsenwinkel en verkoopt vooral elektrische fietsen van rond de € 3.000,00. Bij de kassa biedt zijn medewerker klanten een fietsverzekering tegen diefstal en schade aan. Over andere verzekeringen of financiële producten zegt de winkel niets. Ronald vraagt zich af of hij hiervoor een Wft-vergunning moet aanvragen. Wat is juist?", [["Dit kan vallen onder de vrijstelling voor een verzekering die aanvullend is op de levering van een goed", "De Vrijstellingsregeling Wft kent een vrijstelling voor een verzekering als aanvulling op de levering van een goed, zoals een fiets. Ronald moet wel nagaan of hij aan alle voorwaarden voldoet."], ["De winkel heeft altijd een volledige vergunning voor bemiddelen in schadeverzekeringen nodig, net als een advieskantoor", "Er bestaat juist een vrijstelling voor verzekeringen die aanvullend zijn op de levering van een goed."], ["De Wft is niet van toepassing, omdat de winkel vooral fietsen verkoopt en geen financiële onderneming is", "Wie bemiddelt in verzekeringen valt in beginsel onder de Wft; de hoofdactiviteit van de winkel maakt dat niet anders."], ["Een vergunning is alleen nodig als een klant uitdrukkelijk om advies over de verzekering vraagt", "Ook bemiddelen zonder advies is in beginsel vergunningplichtig; het antwoord hangt hier af van de vrijstelling."]], "1f.38"],
["Een kantoor bemiddelt uitsluitend in particuliere schadeverzekeringen en geeft daarbij nooit advies. Heeft het kantoor een Wft-vergunning nodig?", [["Ja, ook voor bemiddelen zonder advies is in beginsel een vergunning nodig", "De Wft kent een afzonderlijke vergunningplicht voor bemiddelen, los van die voor adviseren."], ["Nee, alleen adviseren is vergunningplichtig", "Bemiddelen is een zelfstandige vergunningplichtige activiteit naast adviseren."], ["Nee, schadeverzekeringen vallen buiten de Wft", "Schadeverzekeringen zijn financiële producten in de zin van de Wft."], ["Alleen als de premie per polis boven een wettelijk grensbedrag van € 1.000,00 per jaar uitkomt", "De vergunningplicht hangt niet af van de hoogte van de premie per polis."]], "1f.38"],
["Welke eis hoort bij het verkrijgen en behouden van een AFM-vergunning als adviseur of bemiddelaar?", [["De dagelijks beleidsbepalers moeten betrouwbaar en geschikt zijn", "De AFM toetst de betrouwbaarheid en geschiktheid van beleidsbepalers bij de vergunningaanvraag en bij wijzigingen."], ["Het kantoor moet lid zijn van een erkende branchevereniging", "Lidmaatschap van een branchevereniging is vrijwillig en geen vergunningseis."], ["Elk advies moet vooraf door de AFM worden goedgekeurd", "De AFM houdt achteraf toezicht en keurt geen individuele adviezen goed."], ["Het kantoor moet met een minimum aantal van vijf aanbieders per productsoort samenwerken", "De Wft schrijft geen minimum aantal aanbieders voor als vergunningseis."]], "1f.33"],
["Wat is het gevolg als een onderneming zonder de vereiste vergunning adviseert over hypotheken?", [["De onderneming overtreedt de Wft; de AFM kan handhavend optreden, bijvoorbeeld met een boete of last onder dwangsom", "Werken zonder vergunning is een overtreding van een kernverbod in de Wft, waartegen de AFM kan optreden."], ["De gegeven adviezen zijn automatisch nietig, zodat de klant geen advieskosten hoeft te betalen en de afgesloten producten vervallen", "De Wft regelt niet dat adviezen automatisch nietig zijn; de civielrechtelijke gevolgen hangen af van de situatie."], ["Kifid legt een boete op en schrapt de onderneming uit het register", "Kifid is geen toezichthouder en legt geen boetes op; dat is de bevoegdheid van de AFM."], ["Er is geen gevolg zolang de klanten tevreden zijn over het advies", "Klanttevredenheid neemt de overtreding van de vergunningplicht niet weg."]], "1f.25"],
["Thijs (32) en Esra (30) wonen samen in een koopwoning en werken allebei fulltime. Over drie maanden krijgen ze hun eerste kind. Esra wil daarna drie dagen per week gaan werken. Ze vragen je wat deze nieuwe levensfase betekent voor hun financiële overzichten. Welke verandering is het meest te verwachten?", [["Hun uitgaven stijgen, bijvoorbeeld door kinderopvang, terwijl hun inkomen daalt doordat Esra minder gaat werken", "Met een kind komen er vaste uitgaven bij, zoals opvang en verzorging. Als Esra minder gaat werken, daalt tegelijk het gezinsinkomen."], ["Hun uitgaven dalen per saldo, omdat zij minder vaak uit eten en op vakantie zullen gaan", "Sommige uitgaven kunnen dalen, maar met een kind stijgen de vaste uitgaven meestal."], ["Er verandert niets, omdat de kinderbijslag alle kosten van een kind volledig dekt", "Kinderbijslag is een tegemoetkoming en dekt lang niet alle kosten van een kind."], ["Hun schulden worden automatisch lager, omdat de hypotheekrente bij gezinsuitbreiding daalt", "De hypotheekrente hangt niet af van gezinsuitbreiding."]], "1a.3"],
["Hoe is de vakbekwaamheid van een medewerker die adviseert over financiële producten opgebouwd?", [["Een Wft-diploma (Basis en de relevante productmodule), actueel gehouden via permanente educatie", "Het diploma toont de vakbekwaamheid aan en via PE blijft die kennis actueel."], ["Een afgeronde hbo-opleiding in een economische richting", "Een algemene opleiding is niet hetzelfde als een Wft-diploma, tenzij die formeel is gelijkgesteld."], ["Een minimum aantal jaren aantoonbare werkervaring in de financiële sector, vastgelegd in een ervaringsverklaring", "Werkervaring alleen is geen vervanging voor het vereiste Wft-diploma."], ["Een eenmalig behaald certificaat dat levenslang geldig blijft", "De kennis moet actueel worden gehouden; zonder PE blijft het diploma niet geldig."]], "1f.33"],
["Een adviseur haalt zijn PE-examen niet vóór het einde van de geldende termijn. Wat is het gevolg?", [["Hij voldoet niet meer aan de vakbekwaamheidseisen en mag die werkzaamheden niet verrichten totdat hij weer voldoet", "Zonder actuele PE is de vakbekwaamheid niet meer aangetoond, zodat de medewerker die werkzaamheden niet mag uitvoeren."], ["Hij krijgt automatisch een jaar uitstel zonder verdere gevolgen", "Er bestaat geen automatisch uitstel; het niet tijdig voldoen heeft direct gevolgen voor de vakbekwaamheid."], ["Alleen zijn werkgever krijgt een waarschuwing van de AFM; de adviseur mag gewoon doorwerken tot de volgende PE-periode", "De medewerker zelf mag niet meer adviseren; de werkgever moet daar ook op toezien."], ["Hij hoeft niets te doen zolang hij al meer dan tien jaar adviseert", "Ervaring vervangt de PE-verplichting niet; die geldt voor iedereen."]], "1f.33"],
["Wie is er volgens de Wft verantwoordelijk voor dat medewerkers met klantcontact vakbekwaam zijn?", [["De financiële onderneming, die ervoor zorgt en kan aantonen dat haar medewerkers vakbekwaam zijn", "De onderneming moet zorgen dat de medewerkers die de werkzaamheden verrichten vakbekwaam zijn en moet dat aantoonbaar maken."], ["Uitsluitend de medewerker zelf, die zijn diploma en PE-bewijzen persoonlijk bij de AFM moet registreren", "De medewerker moet zijn diploma en PE halen, maar de onderneming is wettelijk verantwoordelijk voor de vakbekwaamheid."], ["De AFM, die elke medewerker jaarlijks persoonlijk toetst", "De AFM toetst niet elke medewerker; zij houdt toezicht op de onderneming."], ["De aanbieder van de producten waarover wordt geadviseerd", "Een aanbieder is niet verantwoordelijk voor de vakbekwaamheid van medewerkers van een zelfstandig advieskantoor."]], "1f.33"],
["Sanne (34) en Daan (36) wonen al acht jaar samen in een huurhuis. Ze zijn niet getrouwd, hebben geen geregistreerd partnerschap en hebben geen testament laten opstellen. Daan heeft een flinke spaarrekening op zijn eigen naam. Sanne vraagt wat er met dat geld gebeurt als Daan overlijdt. Wat is juist?", [["Sanne erft niet, omdat ongehuwd samenwonenden zonder testament geen erfgenamen van elkaar zijn", "Het wettelijk erfrecht kent echtgenoten en geregistreerde partners als erfgenaam, maar geen ongehuwde samenwoners. Zonder testament gaat het geld van Daan naar zijn familie."], ["Sanne erft alles, omdat zij al langer dan vijf jaar samenwonen", "De duur van het samenwonen geeft geen erfrecht; daarvoor is een testament nodig."], ["Sanne erft de helft, omdat samenwoners altijd recht hebben op een gelijk deel", "Ongehuwd samenwonenden hebben zonder testament geen wettelijk erfrecht van elkaar."], ["Sanne erft alleen als zij samen een samenlevingscontract hebben, ook als er geen testament is", "Een samenlevingscontract maakt Sanne geen wettelijk erfgenaam; daarvoor is een testament nodig."]], "1a.4"],
["Henk Brouwer (72) overlijdt zonder testament. Hij was getrouwd met Truus (70) en had twee kinderen. Truus wil graag in hun huis blijven wonen. De kinderen vragen wat het wettelijk erfrecht voor hen betekent. Wat is juist volgens de wettelijke verdeling?", [["Truus krijgt de goederen; de kinderen krijgen een geldvordering op haar die meestal pas bij haar overlijden opeisbaar is", "Bij de wettelijke verdeling krijgt de langstlevende echtgenoot alle goederen en de schulden. De kinderen krijgen een vordering ter grootte van hun erfdeel, die in de regel pas bij het overlijden van de langstlevende opeisbaar wordt."], ["Truus en de kinderen worden samen eigenaar van het huis, zodat de kinderen verkoop van het huis kunnen eisen", "De wettelijke verdeling beschermt juist de langstlevende: de goederen gaan naar Truus."], ["De kinderen krijgen alles, omdat Truus via het huwelijk al de helft van het vermogen heeft", "Truus is naast de kinderen erfgenaam en krijgt bij de wettelijke verdeling de goederen."], ["Zonder testament vervalt de nalatenschap van Henk aan de Staat", "De Staat erft alleen als er geen erfgenamen zijn; hier zijn er een echtgenote en twee kinderen."]], "1a.5"],
["Wat is de kern van de algemene zorgplicht voor financiële dienstverleners in de Wft?", [["Zorgvuldig rekening houden met de rechtmatige belangen van de klant", "De algemene zorgplicht vraagt dat de dienstverlener bij zijn dienstverlening zorgvuldig rekening houdt met de rechtmatige belangen van de klant."], ["Zoveel mogelijk producten verkopen binnen de wettelijke grenzen en de eigen acceptatieregels", "Omzet staat niet centraal; de zorgplicht draait om het belang van de klant."], ["De klant alleen informeren als hij daar zelf om vraagt", "De dienstverlener moet ook uit zichzelf relevante informatie geven en zorgvuldig handelen."], ["Altijd het goedkoopste product op de markt garanderen", "De zorgplicht vraagt een passende oplossing, niet per se het goedkoopste product."]], "1f.15"],
["Mark Jansen (38) is net vader geworden en wil snel een overlijdensrisicoverzekering afsluiten. Hij vraagt adviseur Linda om advies over het verzekerde bedrag. Als Linda naar zijn inkomen, zijn hypotheek en zijn vaste lasten vraagt, wil hij daar niets over zeggen. Hij vindt dat privé en wil gewoon een advies. Wat moet Linda doen?", [["Uitleggen dat zij zonder die gegevens geen passend advies kan geven en zich anders van advies onthouden", "Een adviseur moet informatie inwinnen over de financiële positie en de doelen van de klant. Zonder die informatie kan zij niet passend adviseren en geeft zij dus geen advies."], ["Toch adviseren op basis van gemiddelde aannames voor een gezin met een kind, zonder dit vast te leggen", "Een advies op aannames is niet op Mark toegesneden en dus niet passend; bovendien moet de onderbouwing worden vastgelegd."], ["Uit voorzorg de hoogst mogelijke dekking adviseren, zodat het gezin in elk geval genoeg krijgt", "Een te hoge dekking leidt tot een onnodig hoge premie en is evenmin passend."], ["Mark een afstandsverklaring laten tekenen en daarna adviseren op basis van de wel bekende gegevens", "Een afstandsverklaring ontslaat de adviseur niet van de plicht om passend te adviseren."]], "1f.19"],
["Waarom is het belangrijk dat een adviseur het klantprofiel en de onderbouwing van zijn advies in het dossier vastlegt?", [["Zodat achteraf aantoonbaar is op welke informatie het advies berust en waarom het passend was", "Een goed dossier maakt het advies controleerbaar voor de klant, de onderneming en de toezichthouder."], ["Omdat de klant anders geen premie hoeft te betalen", "Het vastleggen van het dossier heeft geen invloed op de betalingsverplichting van de klant."], ["Omdat het dossier vooraf door de AFM moet worden goedgekeurd voordat het advies aan de klant mag worden uitgebracht", "De AFM keurt dossiers niet vooraf goed, maar kan ze wel opvragen bij onderzoek."], ["Omdat de aanbieder anders de polis niet mag afgeven", "De aanbieder heeft eigen acceptatieregels; het adviesdossier is een plicht van de adviseur zelf."]], "2d.1"],
["Met welke vier kenmerken heeft de AFM omschreven wanneer een product of dienst het klantbelang centraal stelt?", [["Kostenefficiënt, nuttig, veilig en begrijpelijk", "Met deze vier kenmerken heeft de AFM uitgewerkt wat klantbelang centraal in de praktijk betekent."], ["Goedkoop, snel, digitaal en flexibel", "Dit zijn wenselijke eigenschappen, maar niet de kenmerken die de AFM hanteert."], ["Rendabel, innovatief, schaalbaar en uniek", "Dit zijn kenmerken vanuit het perspectief van de aanbieder, niet vanuit het klantbelang."], ["Onafhankelijk, provisievrij, garantievrij en eenvoudig", "Deze combinatie is niet de omschrijving die de AFM gebruikt."]], "4a.4"],
["Wat vraagt het productontwikkelingsproces (productgoedkeurings- en reviewproces) van aanbieders van financiële producten?", [["Dat zij producten vooraf toetsen op het klantbelang, een doelgroep bepalen en het product periodiek evalueren", "Aanbieders moeten producten evenwichtig ontwerpen voor een bepaalde doelgroep en die ook na introductie blijven beoordelen."], ["Dat elk nieuw product vooraf door de AFM wordt goedgekeurd", "De AFM keurt producten niet vooraf goed; de aanbieder moet zelf een zorgvuldig proces hebben."], ["Dat zij alleen de winstgevendheid van het product toetsen", "Het proces is juist gericht op het klantbelang en niet alleen op winstgevendheid."], ["Dat producten pas worden aangepast nadat Kifid klachten over het product gegrond heeft verklaard of de AFM daarom vraagt", "Het proces vraagt een proactieve toetsing vooraf en periodiek, niet pas na klachten."]], "1f.33"],
["Wat is de zogenoemde bijzondere zorgplicht die in de civiele rechtspraak voor financiële instellingen is ontwikkeld?", [["Een plicht om vanwege hun deskundigheid en maatschappelijke functie de klant te beschermen, bijvoorbeeld door te waarschuwen voor risico's", "De Hoge Raad heeft deze zorgplicht ontwikkeld; zij geldt naast de publiekrechtelijke Wft-regels."], ["Een Wft-regel die uitsluitend geldt voor de grootste systeembanken en die door de AFM wordt gehandhaafd met bestuurlijke boetes", "De bijzondere zorgplicht komt uit het civiele recht en is niet beperkt tot grote banken."], ["De plicht van de klant om alle risico's van een financieel product zelf te onderzoeken voordat hij een overeenkomst sluit, ook na advies", "Het gaat juist om een plicht van de financiële instelling jegens de klant."], ["De plicht van de AFM om consumenten persoonlijk te waarschuwen", "De bijzondere zorgplicht rust op de instelling, niet op de toezichthouder."]], "1f.15"],
["Anouk Visser (29) wil haar spaargeld beleggen in een offensief aandelenfonds, omdat een collega daar veel mee verdiend zou hebben. Haar adviseur Bram stelt vast dat ze weinig buffer heeft en het geld over drie jaar nodig heeft voor een huis. Hij adviseert haar daarom uitdrukkelijk een defensievere oplossing. Anouk wil toch het risicovolle fonds. Wat is de juiste handelwijze van Bram?", [["Hij legt zijn advies en de risico's helder uit en legt vast dat Anouk daarvan afwijkt", "De klant mag afwijken van het advies. De adviseur zorgt wel dat zij de risico's begrijpt en legt het advies en de afwijking vast."], ["Hij past zijn advies aan haar wens aan en legt alleen dat aangepaste advies in het dossier vast", "Dan klopt het dossier niet met het werkelijke advies en is niet meer te reconstrueren wat hij adviseerde."], ["Hij meldt Anouk bij de AFM, omdat zij een onverantwoorde keuze maakt", "Een klant die van een advies afwijkt doet niets verkeerds; de AFM behandelt zulke situaties niet."], ["Hij regelt het gewenste fonds zonder verder iets vast te leggen, omdat het haar eigen keus is", "Juist bij afwijken van het advies is vastlegging nodig, zodat later duidelijk is wat er is geadviseerd."]], "1f.22"],
["Wat kenmerkt execution only dienstverlening?", [["De klant kiest zelf zonder advies; de dienstverlener doet geen persoonlijke aanbeveling maar moet wel zorgvuldig handelen", "Bij execution only wordt niet geadviseerd, maar de algemene zorgplicht en informatieregels blijven gelden."], ["Er gelden geen Wft-regels, omdat er geen advies wordt gegeven", "Ook zonder advies gelden onder meer de zorgplicht en de informatieverplichtingen."], ["De dienstverlener blijft aansprakelijk voor de passendheid van het gekozen product, net als bij een volledig adviestraject", "Zonder advies is er geen adviesaansprakelijkheid voor passendheid, al blijft zorgvuldigheid nodig."], ["Het is alleen toegestaan bij het openen van een spaarrekening", "Execution only komt bij meer producten voor; voor sommige gelden aanvullende eisen."]], "1f.32"],
["Wat is het doel van het dienstverleningsdocument?", [["De klant vooraf informeren over de aard en kosten van de dienstverlening en de relatie met aanbieders", "Met deze informatie kan de klant bewust kiezen of en bij wie hij advies of bemiddeling afneemt."], ["De klant informeren over de polisvoorwaarden van het geadviseerde product", "Productvoorwaarden komen van de aanbieder; het dienstverleningsdocument gaat over de dienstverlening van het kantoor."], ["Het persoonlijke advies en de onderbouwing daarvan, inclusief het klantprofiel, schriftelijk aan de klant vastleggen", "Dat gebeurt in het adviesrapport, dat pas na de inventarisatie wordt opgesteld."], ["De klant jaarlijks informeren over de waarde van zijn verzekeringen", "Een waarde-overzicht is periodieke productinformatie, geen informatie over de dienstverlening."]], "1f.29"],
["Wanneer moet de klant de informatie over de dienstverlening en de kosten daarvan in beginsel ontvangen?", [["Voordat de dienstverlening begint", "De klant moet vooraf weten wat hij kan verwachten en wat het kost, zodat hij daar een bewuste keuze over kan maken."], ["Bij het ondertekenen van de offerte van de aanbieder", "Dan is de dienstverlening al grotendeels verricht en kan de klant niet meer vooraf kiezen."], ["Na afloop van de dienstverlening, samen met de factuur", "Achteraf informeren over kosten maakt een bewuste keuze vooraf onmogelijk."], ["Alleen wanneer de klant er uitdrukkelijk om vraagt", "Het gaat om een verplichting van de dienstverlener, niet om informatie op verzoek."]], "1f.3"],
["Onder welke voorwaarden mag een adviseur zich onafhankelijk noemen?", [["Als hij adviseert op basis van een analyse van voldoende producten op de markt en geen provisie van aanbieders ontvangt", "De term onafhankelijk is beschermd; zowel een voldoende brede marktanalyse als het ontbreken van provisie van aanbieders is vereist."], ["Als hij niet in loondienst is van een bank of verzekeraar", "Zelfstandig zijn is niet genoeg; de wettelijke voorwaarden gaan over marktanalyse en provisie."], ["Als hij lid is van een beroepsvereniging met een eigen gedragscode en is ingeschreven in het register van die vereniging", "Een lidmaatschap is geen wettelijke voorwaarde voor het gebruik van de term onafhankelijk."], ["Als hij met ten minste twee aanbieders samenwerkt", "Twee aanbieders is niet zonder meer een voldoende aantal, en ook de provisievoorwaarde geldt."]], "1f.37"],
["Welk gestandaardiseerd document moet onder de IDD bij een schadeverzekering worden verstrekt?", [["Het informatiedocument over het verzekeringsproduct (IPID)", "Het IPID geeft in een vast format de kern van een schadeverzekering weer, zoals de dekking en uitsluitingen."], ["Het Europees gestandaardiseerd informatieblad (ESIS)", "Het ESIS hoort bij hypothecair krediet, niet bij schadeverzekeringen."], ["Het essentiële-informatiedocument op grond van de PRIIPs-verordening", "Dit document geldt voor verpakte beleggingsproducten en beleggingsverzekeringen, niet voor schadeverzekeringen."], ["Het standaardformulier Europese informatie inzake consumentenkrediet", "Dit formulier hoort bij consumptief krediet."]], "1f.3"],
["Wat is het ESIS?", [["Een Europees gestandaardiseerd informatieblad met de belangrijkste kenmerken en kosten van een hypotheek", "Door de vaste opbouw kan de consument aanbiedingen van verschillende kredietgevers vergelijken."], ["Een Europese toets op de kredietwaardigheid van de consument, die de geldverstrekker vóór het aanbod moet uitvoeren", "De kredietwaardigheidstoets is een aparte verplichting; het ESIS is een informatiedocument."], ["Een registratie van alle hypotheken in de Europese Unie", "Er bestaat geen Europees hypotheekregister onder deze naam; het ESIS is klantinformatie."], ["Een Europees keurmerk voor duurzame hypotheken", "Het ESIS is geen keurmerk, maar een verplicht informatieblad."]], "1f.2"],
["Wat geeft het jaarlijks kostenpercentage (JKP) bij een krediet weer?", [["De totale kosten van het krediet voor de consument, als jaarlijks percentage van het kredietbedrag", "Het JKP omvat naast de rente ook andere verplichte kosten, zodat kredieten beter vergelijkbaar zijn."], ["Alleen de nominale rente die de kredietgever per jaar in rekening brengt, zonder afsluit- en bemiddelingskosten", "Het JKP is breder dan de nominale rente, omdat ook andere kosten worden meegerekend."], ["Het deel van het krediet dat per jaar moet worden afgelost", "Aflossing is terugbetaling van de hoofdsom en geen kostenpercentage."], ["De verwachte inflatie gedurende de looptijd van het krediet", "Inflatie maakt geen deel uit van het JKP."]], "1c.3"],
["Welke waarschuwingszin moet in reclame voor consumptief krediet worden opgenomen?", [["Let op! Geld lenen kost geld.", "Deze standaardwaarschuwing maakt consumenten erop attent dat lenen niet gratis is."], ["Let op! Lenen is altijd verantwoord.", "Dit is geen wettelijke tekst en zou juist misleidend zijn."], ["Let op! U loopt risico op het verlies van uw inleg.", "Een dergelijke waarschuwing past bij beleggen, niet bij kredietreclame."], ["Let op! Raadpleeg eerst de AFM.", "Dit is geen voorgeschreven tekst; de AFM geeft geen individueel kredietadvies."]], "1c.10"],
["Wat houdt het provisieverbod in?", [["Adviseurs en bemiddelaars mogen voor bepaalde producten geen provisie van de aanbieder ontvangen; de klant betaalt zelf", "Voor onder meer hypotheken en complexe producten is de beloning via de aanbieder vervangen door directe klantbeloning."], ["Adviseurs mogen voor geen enkel product nog beloning ontvangen; het advies moet voortaan door de aanbieder gratis worden gegeven", "Adviseurs mogen wel beloond worden, maar dan door de klant zelf."], ["Aanbieders mogen geen kosten meer in hun producten verwerken", "Het verbod ziet op provisie aan tussenpersonen, niet op alle productkosten."], ["Klanten mogen hun adviseur niet meer per uur betalen", "Uurtarief is juist een gangbare vorm van directe beloning door de klant."]], "1f.8"],
["Ria Smeets (63) wil haar zoon Tim (27) helpen met geld voor een buffer en een nieuwe auto. Ze heeft gehoord dat er bij schenkingen vrijstellingen gelden. Tim heeft nog nooit een grote schenking van zijn moeder ontvangen. Ria vraagt wat het verschil is tussen de jaarlijkse vrijstelling en de eenmalig verhoogde vrijstelling. Wat is juist?", [["De jaarlijkse vrijstelling geldt elk jaar opnieuw; de verhoogde vrijstelling kan Tim als kind van 18 tot 40 jaar één keer benutten", "Voor een schenking van ouder aan kind geldt elk kalenderjaar een vrijstelling. Een kind van 18 tot 40 jaar kan één keer een hogere vrijstelling gebruiken, die in dat jaar in plaats van de gewone vrijstelling komt."], ["De verhoogde vrijstelling mag alleen worden gebruikt voor de aflossing van een eigenwoningschuld van het kind", "Die bestemming hoorde bij de verhoogde vrijstelling voor de eigen woning, die per 2024 is afgeschaft."], ["Er is geen verschil; beide vrijstellingen mogen elk jaar opnieuw volledig worden gebruikt door het kind", "De verhoogde vrijstelling kan maar één keer worden gebruikt."], ["De jaarlijkse vrijstelling geldt alleen voor schenkingen aan kinderen die nog jonger zijn dan 18 jaar", "De jaarlijkse vrijstelling voor kinderen geldt ongeacht hun leeftijd."]], "1a.6"],
["Bij welk van de volgende producten mag een bemiddelaar in beginsel wel provisie van de aanbieder ontvangen?", [["Een inboedelverzekering", "Voor particuliere schadeverzekeringen zoals een inboedelverzekering geldt het provisieverbod niet, al moet de beloning wel transparant en evenwichtig zijn."], ["Een hypothecair krediet", "Voor hypothecair krediet geldt het provisieverbod."], ["Een arbeidsongeschiktheidsverzekering voor een particulier", "Arbeidsongeschiktheidsverzekeringen vallen onder het provisieverbod."], ["Een beleggingsverzekering", "Een beleggingsverzekering is een complex product en valt onder het provisieverbod."]], "1f.12"],
["Wat was een belangrijke reden voor de invoering van het provisieverbod?", [["Het wegnemen van de prikkel om te adviseren wat de meeste provisie oplevert in plaats van wat het best bij de klant past", "Provisie van de aanbieder kon het advies sturen; directe beloning maakt de kosten zichtbaar en het advies zuiverder."], ["Het verlagen van de rente op hypotheken voor alle consumenten", "Het verbod was niet bedoeld om rentes te verlagen, maar om belangenconflicten te beperken."], ["Het beperken van het aantal adviseurs in Nederland", "Doel was een betere kwaliteit van advies, niet minder adviseurs."], ["Het mogelijk maken dat aanbieders zelf meer adviseurs in dienst nemen en hun producten rechtstreeks aan consumenten verkopen", "Het provisieverbod geldt ook voor advies door aanbieders; het ging om het zuiveren van advies."]], "1f.8"],
["Sandra Mulder is eigenaar van een advieskantoor dat jaarlijks zo'n tweehonderd hypotheken adviseert. Een geldverstrekker belt haar met een aanbod. Als het kantoor dit jaar minimaal vijftig hypotheken bij hem onderbrengt, mogen twee adviseurs gratis mee op een studiereis naar Lissabon. Sandra twijfelt of ze daarop kan ingaan. Wat is juist?", [["Dit is niet toegestaan, omdat ook een vergoeding in natura van de aanbieder onder het provisieverbod valt", "Bij hypothecair krediet mag een adviseur geen provisie van de aanbieder ontvangen, ook niet in natura. Een reis die afhangt van het aantal hypotheken is bovendien een sterke prikkel tegen het klantbelang."], ["Dit is toegestaan, omdat het om een reis gaat en niet om een geldbedrag", "Het provisieverbod geldt ook voor vergoedingen in natura."], ["Dit is toegestaan, zolang de klanten van het kantoor er niets extra voor betalen", "Het gaat om de prikkel bij de adviseur, niet om wat de klant betaalt."], ["Dit is toegestaan als het kantoor de reis duidelijk in het dienstverleningsdocument vermeldt", "Transparantie maakt een verboden vergoeding niet toegestaan."]], "1f.8"],
["Wat geldt voor de beloning van medewerkers met klantcontact bij een financiële onderneming?", [["De beloning mag geen prikkel geven om in strijd met het belang van de klant te handelen", "Beloningsbeleid moet zo zijn ingericht dat medewerkers niet worden aangezet tot het verkopen van producten die niet in het belang van de klant zijn."], ["De beloning moet volledig afhangen van het aantal afgesloten producten, zodat de productie van het kantoor stijgt", "Een volledig productiegebonden beloning geeft juist een prikkel tegen het klantbelang."], ["Er gelden geen regels, zolang het vaste salaris marktconform is", "Ook voor variabele beloning en het beloningsbeleid gelden wettelijke regels."], ["Alleen bestuurders vallen onder beloningsregels, medewerkers niet", "Beloningsregels gelden ook voor medewerkers, in het bijzonder voor wie met klanten werkt."]], "1f.12"],
["Wat is de juiste aanpak van belangenconflicten volgens de regelgeving?", [["Belangenconflicten identificeren, voorkomen of beheersen, en de klant informeren als dat onvoldoende lukt", "Melden aan de klant is het sluitstuk; eerst moet de onderneming het conflict zelf voorkomen of beheersen."], ["Belangenconflicten alleen in de algemene voorwaarden vermelden, zodat de klant er bij het tekenen mee instemt", "Een algemene vermelding is geen beheersing van het concrete conflict."], ["Belangenconflicten alleen melden als de klant ernaar vraagt", "De onderneming moet zelf actief belangenconflicten signaleren en aanpakken."], ["Belangenconflicten zijn toegestaan zolang de AFM er niet naar vraagt", "Er geldt een eigen verplichting om belangenconflicten te beheersen, los van vragen van de AFM."]], "4a.4"],
["Rob Hendriks is zelfstandig hypotheekadviseur. Privé bezit hij een flink aandelenpakket in een kleine geldverstrekker, waarvan hij ook regelmatig hypotheken adviseert. Zijn klant Jeroen krijgt van Rob het advies om juist bij deze geldverstrekker te lenen. Jeroen weet niets van de aandelen van Rob. Wat is juist?", [["Er is een belangenconflict dat Rob moet beheersen en waarover hij Jeroen duidelijk moet informeren", "Het eigen financiële belang van Rob kan zijn advies beïnvloeden. Hij moet dat conflict beheersen en, als dat niet volstaat, Jeroen er vooraf duidelijk over informeren."], ["Er is geen probleem, omdat de aandelen privébezit zijn en buiten zijn onderneming vallen", "Ook een privébelang kan het advies beïnvloeden en is dus een belangenconflict."], ["Rob mag deze geldverstrekker nooit meer adviseren, ook niet als dat voor de klant het beste is", "Een belangenconflict moet worden beheerst en gemeld; een absoluut verbod volgt er niet uit."], ["Het is alleen relevant als Jeroen zelf aandelen heeft in deze geldverstrekker", "Het gaat om het belang van de adviseur, niet om dat van de klant."]], "4a.4"],
["Adviseur Fatma Yilmaz heeft al jaren de familie Bos als klant. De familie verkoopt haar woning aan het jonge stel Kevin en Iris. Kevin en Iris vragen Fatma hun hypotheek te regelen, terwijl de familie Bos haar vraagt mee te denken over de financiële afwikkeling van de verkoop. Fatma vraagt zich af of ze beide opdrachten kan aannemen. Wat is juist?", [["Er is een belangenconflict, omdat de belangen van koper en verkoper tegengesteld kunnen zijn", "Koper en verkoper hebben bijvoorbeeld tegengestelde belangen bij prijs en voorwaarden. Fatma moet dit conflict voorkomen of beheersen en kan zo nodig een van de opdrachten weigeren."], ["Er is geen belangenconflict, omdat het om één en dezelfde woning gaat", "Juist omdat het om dezelfde transactie gaat, kunnen de belangen botsen."], ["Er is geen belangenconflict zolang beide partijen tevreden zijn met de uitkomst", "Een belangenconflict hangt niet af van tevredenheid achteraf, maar van tegengestelde belangen vooraf."], ["Er is alleen een belangenconflict als Fatma ook als makelaar bij de verkoop optreedt", "Ook zonder makelaarsrol kan advies aan beide kanten tot een belangenconflict leiden."]], "4a.4"],
["Wat moet een financiële onderneming vastleggen met betrekking tot belangenconflicten?", [["Een beleid voor belangenconflicten en een registratie van situaties waarin die zijn ontstaan of kunnen ontstaan", "Vastlegging maakt het beheersen van belangenconflicten controleerbaar voor de onderneming en de toezichthouder."], ["Alleen de belangenconflicten die tot een klacht hebben geleid", "Ook conflicten zonder klacht moeten worden gesignaleerd en beheerst."], ["Niets, omdat belangenconflicten uitsluitend mondeling met de betrokken klant en de compliance officer worden besproken", "Mondeling bespreken is onvoldoende; het beleid en de registratie moeten aantoonbaar zijn."], ["Alleen belangenconflicten van bestuurders, niet van medewerkers", "Ook medewerkers kunnen belangenconflicten hebben die beheerst moeten worden."]], "1f.33"],
["Wat moet een consument doen voordat hij met een klacht bij Kifid terechtkan?", [["Eerst de klacht voorleggen aan de financiële dienstverlener zelf", "Kifid behandelt een klacht pas als de interne klachtenprocedure van de dienstverlener niet tot een oplossing heeft geleid."], ["Eerst een procedure bij de kantonrechter beginnen", "Kifid is juist een alternatief voor de rechter; een rechtszaak vooraf is niet nodig."], ["Eerst toestemming vragen aan de AFM", "De AFM speelt geen rol in de toegang tot Kifid."], ["Eerst een advocaat inschakelen die de klacht namens hem schriftelijk indient", "Een consument kan zelf een klacht indienen; een advocaat is niet verplicht."]], "1f.5"],
["Kevin de Bruin (29) heeft schulden bij zes schuldeisers, waaronder een creditcard en een achterstand bij zijn zorgverzekeraar. Hij kan de betalingen niet meer bijhouden en krijgt steeds meer aanmaningen. Hij vraagt bij de bank wat hij kan doen. Hij heeft gehoord van schuldsanering via de rechter. Wat leg je hem in hoofdlijnen uit?", [["Hij kan schuldhulp via de gemeente vragen; lukt een minnelijke regeling niet, dan kan de rechter hem toelaten tot de Wsnp", "Eerst wordt geprobeerd met alle schuldeisers een minnelijke regeling te treffen, bijvoorbeeld via de gemeentelijke schuldhulpverlening. Mislukt dat, dan kan hij de rechter vragen om toelating tot de wettelijke schuldsaneringsregeling (Wsnp)."], ["Hij kan rechtstreeks bij de AFM een schuldsanering aanvragen, die zijn schulden direct kwijtscheldt", "De AFM is toezichthouder en regelt geen schuldsanering voor consumenten."], ["Hij kan het BKR verzoeken zijn schulden te laten vervallen en zijn registraties te verwijderen", "Het BKR registreert kredieten en achterstanden, maar scheldt geen schulden kwijt."], ["Hij kan zijn schulden oversluiten in een nieuw doorlopend krediet, waarmee de sanering vanzelf begint", "Oversluiten is geen schuldsanering en kan zijn situatie verergeren; bij problematische schulden is schuldhulpverlening de aangewezen weg."]], "1a.12"],
["Een consument heeft een niet-bindende uitspraak van Kifid gekregen en is het daar niet mee eens. Wat kan hij doen?", [["Hij kan de zaak alsnog aan de rechter voorleggen", "Een niet-bindende uitspraak is een advies; partijen kunnen daarna naar de rechter."], ["Niets, iedere uitspraak van Kifid is definitief", "Alleen een bindende uitspraak bindt partijen; een niet-bindende uitspraak niet."], ["Hij moet de AFM vragen de uitspraak te herzien", "De AFM heeft geen bevoegdheid om uitspraken van Kifid te herzien."], ["Hij kan alleen een nieuwe klacht bij dezelfde commissie indienen", "Dezelfde klacht opnieuw indienen is geen gangbare route; de rechter staat open."]], "1f.21"],
["Wat hoort bij een zorgvuldige interne klachtafhandeling door een advieskantoor?", [["Klachten registreren, tijdig en inhoudelijk reageren en ze analyseren om herhaling te voorkomen", "Een goede procedure lost de klacht op en gebruikt de les om de dienstverlening te verbeteren."], ["Klachten alleen behandelen als ze per aangetekende brief en binnen zes weken na het advies worden ingediend", "Een dergelijke drempel past niet bij een toegankelijke klachtenprocedure."], ["Klachten direct doorsturen naar Kifid zonder eigen reactie", "Het kantoor moet eerst zelf de klacht behandelen."], ["Klachten pas registreren als de klant een schadevergoeding eist", "Ook klachten zonder schadeclaim horen geregistreerd en behandeld te worden."]], "3c.1"],
["Meneer Van Dam belt het kantoor. Hij wacht al drie weken op de beloofde offerte voor zijn inboedel- en opstalverzekering en is daar flink boos over. Hij zegt dat hij geen zin heeft om ook nog een brief te schrijven en hangt op. Je collega vindt dat dit geen klacht is, omdat er niets op papier staat. Wat is juist?", [["Dit is een klacht die volgens de klachtenprocedure moet worden behandeld en geregistreerd", "Ook een mondelinge uiting van ontevredenheid is een klacht. Die wordt vastgelegd en afgehandeld, bijvoorbeeld door meneer Van Dam terug te bellen."], ["Dit is geen klacht, omdat alleen schriftelijke klachten in de registratie meetellen", "Een klacht hoeft niet schriftelijk te zijn om als klacht te worden behandeld."], ["Dit is een zaak voor Kifid, dus het kantoor hoeft zelf niets te doen", "Een klacht wordt eerst door de dienstverlener zelf behandeld; Kifid komt pas daarna."], ["Dit is pas een klacht als meneer Van Dam aantoonbaar financiële schade heeft geleden", "Ontevredenheid over de dienstverlening is al een klacht, ook zonder schade."]], "3c.1"],
["Waaruit bestaat het cliëntenonderzoek onder de Wwft?", [["Identificatie en verificatie van cliënt en UBO, vaststellen van doel en aard van de relatie en doorlopende controle", "Het cliëntenonderzoek is meer dan een identiteitscheck: ook het doel van de relatie en voortdurende monitoring horen erbij."], ["Alleen het kopiëren van het identiteitsbewijs van de cliënt", "Identificatie is maar één onderdeel; ook verificatie, UBO, doel en monitoring zijn nodig."], ["Een kredietcheck bij het BKR en een inkomenstoets", "Dit zijn kredietwaardigheidscontroles, geen onderdelen van het Wwft-cliëntenonderzoek."], ["Het opvragen van een verklaring omtrent het gedrag van de cliënt en een recent uittreksel uit de Basisregistratie Personen", "Een VOG en een BRP-uittreksel zijn geen onderdelen van het cliëntenonderzoek onder de Wwft."]], "2b.1"],
["Bij welke instantie meldt een Wwft-plichtige onderneming een ongebruikelijke transactie?", [["FIU-Nederland", "De Financial Intelligence Unit ontvangt en analyseert meldingen van ongebruikelijke transacties."], ["De politie", "De melding gaat naar FIU-Nederland, dat zo nodig gegevens doorgeeft aan opsporingsinstanties."], ["De AFM", "De AFM houdt toezicht op naleving, maar is niet het meldpunt voor ongebruikelijke transacties."], ["De Belastingdienst", "De Belastingdienst is niet het meldpunt onder de Wwft."]], "4a.3"],
["Adviseur Joyce heeft vorige maand een ongebruikelijke transactie van haar klant Arjen Kok gemeld bij FIU-Nederland. Arjen had een grote koopsom voor een lijfrente betaald uit een onduidelijke bron. Nu belt hij haar op. Hij heeft het gevoel dat er iets niet klopt en vraagt of er iets met zijn dossier aan de hand is. Wat mag Joyce zeggen?", [["Zij mag niet vertellen dat er een melding is gedaan", "Over een melding geldt een geheimhoudingsplicht: de klant mag niet te weten komen dat hij is gemeld. Joyce voert het gesprek dus neutraal."], ["Zij moet Arjen volledig informeren over de melding en de reden ervan", "Dat is in strijd met de geheimhoudingsplicht rond meldingen."], ["Zij mag het vertellen als Arjen schriftelijk om inzage in zijn dossier vraagt", "Ook een inzageverzoek doorbreekt de geheimhoudingsplicht rond een melding niet."], ["Zij mag het vertellen, omdat de transactie al is uitgevoerd", "Ook na uitvoering van de transactie blijft de geheimhoudingsplicht gelden."]], "4a.3"],
["Hanneke Vermeulen wil als nieuwe klant een grote koopsom storten voor een lijfrenteverzekering. Bij het cliëntenonderzoek blijkt dat zij lid is van de Tweede Kamer. Haar dossier ziet er verder netjes uit. Je collega vindt dat zij gewoon een klant als ieder ander is. Wat is juist?", [["Verscherpt cliëntenonderzoek, onder meer naar de herkomst van haar vermogen, met goedkeuring op hoger niveau", "Een Kamerlid is een politiek prominent persoon. Dan gelden verscherpte maatregelen, zoals onderzoek naar de herkomst van het vermogen en goedkeuring door hoger leidinggevend personeel."], ["Het kantoor mag geen zakelijke relatie aangaan met een politiek prominent persoon", "Een relatie met een PEP is toegestaan, maar vraagt verscherpte maatregelen."], ["Er gelden dezelfde maatregelen als bij iedere andere klant, omdat haar dossier netjes is", "Voor een PEP schrijft de Wwft verscherpt cliëntenonderzoek voor."], ["Het kantoor moet haar eerst melden bij FIU-Nederland en wachten op toestemming", "Een PEP-status is op zichzelf geen ongebruikelijke transactie, en FIU-Nederland geeft geen toestemming vooraf."]], "2b.1"],
["Hoe lang moeten gegevens uit het cliëntenonderzoek onder de Wwft ten minste worden bewaard?", [["Vijf jaar na het einde van de zakelijke relatie of na uitvoering van de transactie", "De Wwft schrijft deze termijn voor, zodat gegevens beschikbaar zijn voor onderzoek."], ["Zeven jaar na het aangaan van de zakelijke relatie, gelijk aan de fiscale bewaarplicht voor de administratie", "Zeven jaar is de fiscale bewaarplicht; de Wwft hanteert een andere termijn en een ander startpunt."], ["Eén jaar na de laatste transactie", "Die termijn is te kort voor de Wwft."], ["Zolang de klant daarmee instemt", "De bewaarplicht is wettelijk en hangt niet af van de instemming van de klant."]], "2d.1"],
["Wat beschermt een melder die te goeder trouw een ongebruikelijke transactie meldt?", [["Hij is gevrijwaard van strafrechtelijke en civielrechtelijke aansprakelijkheid voor de melding", "De Wwft beschermt de melder te goeder trouw, zodat de meldplicht niet tot aansprakelijkheid leidt."], ["Hij krijgt een financiële beloning van FIU-Nederland", "Er is geen beloning voor een melding."], ["Hij krijgt automatisch een nieuwe identiteit", "Dat is geen onderdeel van de Wwft-regeling."], ["Hij is niet beschermd en draagt zelf het risico van een schadeclaim van de klant over wie hij heeft gemeld", "De Wwft biedt juist bescherming aan melders te goeder trouw."]], "4a.3"],
["Erik Smits meldt zich namens een holding-bv bij het kantoor voor een levensverzekering die de bv voor haar directeur wil sluiten. Op de vraag wie de uiteindelijke belanghebbenden van de bv zijn, reageert hij ontwijkend. Hij zegt dat de aandeelhouders liever anoniem blijven. Ook na doorvragen krijg je geen duidelijkheid. Wat moet het kantoor doen?", [["Geen relatie aangaan, omdat het cliëntenonderzoek niet kan worden voltooid, en een melding overwegen", "Kan de UBO niet worden vastgesteld, dan mag de relatie niet worden aangegaan. De weigering kan bovendien een reden zijn om een ongebruikelijke transactie te melden."], ["De relatie aangaan en het UBO-onderzoek later afronden, als de polis eenmaal loopt", "Het cliëntenonderzoek moet in beginsel zijn afgerond voordat de relatie begint."], ["De relatie aangaan als Erik verklaart dat hij zelf de enige bestuurder van de bv is", "Bestuurder zijn zegt niets over wie de uiteindelijke belanghebbenden zijn."], ["De relatie aangaan, omdat de UBO-plicht alleen voor banken en trustkantoren geldt", "Ook een Wwft-plichtige bemiddelaar moet de UBO vaststellen."]], "1b.3"],
["Op welke grondslag verwerkt een adviseur doorgaans de inkomensgegevens van een klant om een hypotheekadvies te geven?", [["De verwerking is noodzakelijk voor de uitvoering van de overeenkomst met de klant", "Zonder inkomensgegevens kan het gevraagde advies niet worden gegeven; dat is een eigen grondslag naast toestemming."], ["Toestemming van de klant is altijd vereist en is de enige mogelijke grondslag voor financiële gegevens", "De AVG kent zes grondslagen; toestemming is er één van en is niet altijd de meest passende."], ["Het vitale belang van de klant", "Deze grondslag is bedoeld voor levensbedreigende situaties, niet voor advies."], ["Het algemeen belang van een goed werkende hypotheekmarkt", "Deze grondslag geldt voor taken van algemeen belang, niet voor een advies aan een klant."]], "1f.40"],
["Adviseur Tim laat na een klantbezoek zijn laptop in de trein liggen. Op de laptop staan onversleutelde dossiers van zo'n zestig klanten, met inkomensgegevens en kopieën van paspoorten. De laptop wordt niet teruggevonden. Tim wil het voorval het liefst stil houden. Wat moet het kantoor doen?", [["Het datalek in beginsel binnen 72 uur melden bij de Autoriteit Persoonsgegevens en zo nodig de klanten informeren", "Een datalek met risico voor betrokkenen wordt in beginsel binnen 72 uur bij de AP gemeld. Bij een hoog risico, zoals hier met paspoortkopieën, worden ook de klanten geïnformeerd."], ["Het lek alleen intern registreren, omdat het om een ongelukje van één medewerker gaat", "Ook onbedoeld verlies is een datalek; met dit risico moet het bij de AP worden gemeld."], ["Het lek binnen 72 uur melden bij de AFM, omdat het om financiële gegevens van klanten gaat", "Datalekken worden gemeld bij de Autoriteit Persoonsgegevens, niet bij de AFM."], ["Afwachten of een klant schade meldt en pas dan actie ondernemen", "De meldplicht hangt niet af van een klacht of gemelde schade."]], "4a.5"],
["Welke van de volgende gegevens is een bijzonder persoonsgegeven onder de AVG?", [["Informatie over de gezondheid van de klant", "Gezondheidsgegevens zijn bijzondere persoonsgegevens; verwerking is in beginsel verboden behalve onder specifieke uitzonderingen."], ["Het bruto jaarinkomen en de vermogenspositie van de klant", "Inkomen en vermogen zijn gevoelig, maar geen bijzondere persoonsgegevens in de zin van de AVG."], ["Het woonadres van de klant", "Een adres is een gewoon persoonsgegeven."], ["Het e-mailadres van de klant", "Een e-mailadres is een gewoon persoonsgegeven."]], "1f.40"],
["Een klant vraagt het kantoor welke persoonsgegevens het van hem heeft. Wat geldt?", [["De klant heeft recht op inzage en het kantoor moet in beginsel binnen een maand reageren", "De AVG geeft een inzagerecht; de termijn kan bij complexe verzoeken worden verlengd."], ["Het kantoor hoeft alleen te reageren als de klant een advocaat inschakelt", "Het inzagerecht kan de klant zelf uitoefenen."], ["Het kantoor mag een inzageverzoek altijd weigeren vanwege bedrijfsgeheimen of de interne adviesnotities", "Weigeren kan alleen in uitzonderlijke gevallen; het recht op inzage is het uitgangspunt."], ["Het kantoor moet de gegevens eerst aan de AFM voorleggen", "De AFM speelt geen rol bij inzageverzoeken onder de AVG."]], "1f.39"],
["Mag een adviseur gegevens die hij voor een hypotheekadvies heeft verkregen zonder meer gebruiken voor een marketingactie van een partnerbedrijf?", [["Nee, gegevens mogen alleen voor verenigbare doelen worden gebruikt; voor een ander doel is een eigen grondslag nodig", "Het beginsel van doelbinding voorkomt dat gegevens ongemerkt voor nieuwe doelen worden gebruikt."], ["Ja, zodra gegevens zijn verkregen mogen ze vrij worden gebruikt", "De AVG kent doelbinding; vrij gebruik is niet toegestaan."], ["Ja, als het partnerbedrijf ook een financiële onderneming is met een eigen AFM-vergunning en een gepubliceerde privacyverklaring", "Het type ontvanger verandert niets aan de eis van een passende grondslag."], ["Ja, als de klant niet binnen een week bezwaar maakt", "Stilzwijgen geldt niet als toestemming onder de AVG."]], "4a.5"],
["Een kantoor laat zijn klantdossiers opslaan door een externe softwareleverancier. Wat is juist?", [["Het kantoor moet een verwerkersovereenkomst sluiten en blijft verwerkingsverantwoordelijke", "De leverancier verwerkt gegevens in opdracht en is verwerker; het kantoor blijft verantwoordelijk."], ["De leverancier wordt automatisch de enige verwerkingsverantwoordelijke", "Het kantoor bepaalt het doel en de middelen en blijft verantwoordelijk."], ["Er zijn geen afspraken nodig, omdat de leverancier zelf de AVG moet naleven en daarvoor zelf aansprakelijk is", "De AVG eist juist schriftelijke afspraken met een verwerker."], ["Alleen toestemming van iedere klant is vereist", "Het gaat hier om een verwerkersrelatie, die een overeenkomst vereist en geen toestemming."]], "4a.5"],
["Wie moeten de eed of belofte financiële sector afleggen?", [["Niet alleen bestuurders, maar ook medewerkers van een financiële onderneming in Nederland, bijvoorbeeld met klantcontact", "De eed of belofte geldt voor bestuurders en commissarissen en ook voor veel medewerkers, zoals degenen die rechtstreeks met klanten werken."], ["Uitsluitend bestuurders en commissarissen van banken en verzekeraars die onder prudentieel toezicht van DNB staan", "De verplichting is breder en geldt ook voor medewerkers, en niet alleen bij banken."], ["Alleen adviseurs die zelfstandig ondernemer zijn", "De eed is niet beperkt tot zelfstandigen; juist medewerkers in dienst vallen er ook onder."], ["Alleen medewerkers die een strafblad hebben gehad", "De eed is een algemene integriteitsverklaring en hangt niet af van het verleden van de medewerker."]], "4a.4"],
["Wat is de strekking van de eed of belofte financiële sector?", [["Integer en zorgvuldig handelen, het klantbelang centraal stellen en het vertrouwen in de financiële sector bevorderen", "De eed onderstreept de persoonlijke verantwoordelijkheid van medewerkers voor een integere sector."], ["De belofte om de winst van de werkgever zo groot mogelijk te maken en de aandeelhouders daarover jaarlijks te informeren", "De eed draait niet om winst, maar om integriteit en klantbelang."], ["De belofte om nooit een fout te maken in een advies", "Fouten zijn menselijk; de eed gaat over integer en zorgvuldig handelen."], ["De belofte om alleen producten van de eigen werkgever aan te bieden", "De eed bevat geen productvoorkeur; het belang van de klant staat centraal."]], "4a.4"],
["Lisa (28) en Ahmed (30) gaan samenwonen en openen samen een en/of-rekening voor de vaste lasten. Lisa vraagt wat dit betekent voor het geld op de rekening. Ahmed wil weten wie aansprakelijk is als de rekening rood staat. Ze vragen jou om uitleg. Wat is juist?", [["Ieder kan zelfstandig over de rekening beschikken en beiden zijn hoofdelijk aansprakelijk voor een tekort", "Bij een en/of-rekening mag elke rekeninghouder zonder de ander geld opnemen of overmaken. Staat de rekening rood, dan kan de bank het hele tekort op ieder van hen verhalen."], ["Alleen beiden samen kunnen een betaling doen, en ieder is aansprakelijk voor de helft", "Dat lijkt op een en-rekening; bij een en/of-rekening kan ieder zelfstandig beschikken en is ieder voor het geheel aansprakelijk."], ["Ieder kan zelfstandig beschikken, maar alleen de eerste rekeninghouder is aansprakelijk", "Bij een en/of-rekening zijn beide rekeninghouders hoofdelijk aansprakelijk."], ["Het saldo is van ieder voor de helft, zodat de bank opnames boven die helft weigert", "De bank controleert niet wie welk deel opneemt; ieder mag zelfstandig beschikken."]], "1b.1"],
["Wat wordt verstaan onder een integriteitsrisico voor een financiële onderneming?", [["Het risico op aantasting van reputatie of vermogen door niet-integer gedrag, zoals fraude of witwassen", "Een integere bedrijfsvoering vraagt dat de onderneming deze risico's analyseert en beheerst."], ["Het risico dat de rente op de kapitaalmarkt stijgt", "Dat is een marktrisico, geen integriteitsrisico."], ["Het risico dat een klant zijn premie niet op tijd betaalt", "Dat is een kredietrisico, geen integriteitsrisico."], ["Het risico dat de software van het kantoor verouderd raakt en klantgegevens daardoor onbereikbaar worden", "Dat is een operationeel of IT-risico, geen integriteitsrisico in de eigenlijke zin."]], "4a.3"],
["Starters Sem en Julia willen een appartement kopen, maar hun inkomen is net te laag voor de gewenste hypotheek. Je collega Patrick stelt voor om in de aanvraag een paar honderd euro meer inkomen op te nemen dan op de werkgeversverklaring staat. Volgens hem wordt daar niemand slechter van. Sem en Julia weten van niets. Wat is de juiste reactie?", [["Niet meewerken en het voorval intern melden, bijvoorbeeld bij compliance of de leidinggevende", "Een te hoog inkomen opgeven is fraude en kan de klanten in financiële problemen brengen. Je werkt niet mee en meldt het volgens de interne procedure."], ["Meewerken, omdat Sem en Julia daardoor toch het appartement kunnen kopen", "Fraude is nooit in het belang van de klant; zij krijgen een lening die ze mogelijk niet kunnen dragen."], ["Meewerken, zolang het verschil maar een paar honderd euro is", "De omvang maakt geen verschil; ook een kleine aanpassing is fraude."], ["Niets doen en het aan de geldverstrekker overlaten om de gegevens te controleren", "Wegkijken past niet bij integer handelen; je moet het voorval melden."]], "4a.3"],
["Wat kenmerkt een annuïteitenlening bij een gelijkblijvende rente?", [["De bruto maandlast blijft gelijk; het rentedeel daalt en het aflossingsdeel stijgt", "Bij annuïteiten verschuift de samenstelling van de vaste termijn geleidelijk van rente naar aflossing."], ["Er wordt elke maand hetzelfde bedrag afgelost, zodat de bruto maandlast in de loop van de tijd daalt", "Dit is het kenmerk van een lineaire lening."], ["Er wordt pas aan het einde van de looptijd in één keer afgelost", "Dit kenmerkt een aflossingsvrije lening."], ["Het rentedeel blijft gelijk en het aflossingsdeel daalt", "Het rentedeel daalt juist, omdat de schuld steeds kleiner wordt."]], "1c.23"],
["Ilse en Ruben lenen € 200.000,00 voor hun woning, met een looptijd van 30 jaar en een vaste rente voor de hele looptijd. Ze twijfelen tussen annuïtair en lineair aflossen. Ilse wil in het begin een zo laag mogelijke maandlast. Ruben wil over de hele looptijd zo weinig mogelijk rente betalen. Welke uitspraak is juist?", [["Lineair geeft in totaal minder rente, maar annuïtair geeft in het begin een lagere bruto maandlast", "Bij lineair wordt vanaf het begin sneller afgelost, dus dalen de schuld en de rente sneller. De bruto maandlast is daardoor in het begin wel hoger dan bij annuïtair."], ["Annuïtair geeft in totaal minder rente en ook in het begin de laagste bruto maandlast", "Bij annuïtair wordt in het begin minder afgelost, dus wordt over de hele looptijd juist meer rente betaald."], ["Beide vormen leiden tot dezelfde totale rente, omdat het bedrag en de looptijd gelijk zijn", "De totale rente hangt af van hoe snel de schuld daalt, en dat verschilt per aflossingsvorm."], ["Lineair geeft in totaal minder rente en ook in het begin de laagste bruto maandlast", "Bij lineair is de eerste maandlast juist het hoogst, omdat vanaf het begin een vast bedrag wordt afgelost."]], "1c.23"],
["Noor (24) heeft net haar eerste baan en zet € 2.000,00 op een spaarrekening met een rente van 5% per jaar. Ze laat het geld twee jaar staan en neemt niets op. De rente wordt elk jaar bijgeschreven en gaat daarna meerenten. Ze vraagt je wat er na twee jaar op haar rekening staat. Wat is het juiste bedrag?", [["€ 2.205,00", "Na een jaar staat er € 2.100,00. In het tweede jaar komt daar 5% over € 2.100,00 bij, dus € 105,00, samen € 2.205,00."], ["€ 2.200,00", "Dat is enkelvoudige rente; de rente over de rente van het eerste jaar ontbreekt."], ["€ 2.100,00", "Dat is het saldo na één jaar, niet na twee jaar."], ["€ 2.250,00", "Dit bedrag is te hoog; bij 5% per jaar komt er in twee jaar € 205,00 bij."]], "2a.1"],
["De spaarrente bedraagt 2% en de inflatie 3%. Wat gebeurt er met de koopkracht van het spaargeld, belastingen buiten beschouwing gelaten?", [["De koopkracht daalt, omdat de prijzen sneller stijgen dan het spaartegoed groeit", "Het reële rendement is negatief; met het tegoed kan na een jaar minder worden gekocht."], ["De koopkracht stijgt, omdat er rente wordt bijgeschreven", "De nominale groei is lager dan de prijsstijging, dus de koopkracht stijgt niet."], ["De koopkracht blijft gelijk, omdat rente en inflatie elkaar over een heel jaar gemeten opheffen", "Rente en inflatie zijn hier niet gelijk; de inflatie is hoger."], ["De koopkracht hangt alleen af van de hoogte van het saldo", "Koopkracht wordt bepaald door de verhouding tussen tegoed en prijsniveau."]], "1b.15"],
["Wim Peters (71) heeft € 80.000,00 op een spaarrekening en € 40.000,00 op een betaalrekening, allebei bij bank A. Daarnaast heeft hij € 30.000,00 op een spaarrekening bij bank B, een andere bank met een eigen vergunning. Bank A gaat failliet. Wim vraagt zich af hoeveel van zijn geld beschermd is. Hoeveel krijgt hij via het depositogarantiestelsel van zijn tegoed bij bank A terug?", [["€ 100.000,00", "Het depositogarantiestelsel beschermt € 100.000,00 per rekeninghouder per bank, voor alle rekeningen bij die bank samen. Van de € 120.000,00 bij bank A is € 20.000,00 dus niet gedekt."], ["€ 120.000,00", "De dekking geldt per rekeninghouder per bank, niet per rekening; boven € 100.000,00 is er geen garantie."], ["€ 80.000,00", "Ook tegoeden op een betaalrekening vallen onder het depositogarantiestelsel."], ["€ 70.000,00", "Het tegoed bij bank B telt niet mee; die bank is niet failliet en valt onder een eigen dekking."]], "1b.21"],
["Wat houdt het indemniteitsbeginsel bij schadeverzekeringen in?", [["De uitkering is niet hoger dan de werkelijk geleden schade; de verzekerde mag er niet beter van worden", "Een schadeverzekering vergoedt het verlies en is niet bedoeld om winst te maken."], ["De verzekeraar keert altijd het verzekerde bedrag uit, ongeacht de schade", "Dat kenmerkt een sommenverzekering, niet een schadeverzekering."], ["De verzekerde mag dezelfde schade bij meerdere verzekeraars volledig claimen, mits hij elke polis zelf betaalt", "Dubbel vergoeden zou de verzekerde verrijken, wat het beginsel juist uitsluit."], ["De premie wordt achteraf vastgesteld op basis van de schade", "Het beginsel gaat over de uitkering, niet over de premievaststelling."]], "1g.15"],
["Annelies en Koen wonen al twintig jaar in hetzelfde huis en hebben hun inboedelverzekering in al die tijd nooit aangepast. De inboedel is verzekerd voor € 30.000,00, maar blijkt na een brand € 60.000,00 waard te zijn. De brand veroorzaakt € 10.000,00 schade. Hun polis heeft geen garantie tegen onderverzekering. Wat keert de verzekeraar volgens de evenredigheidsregel uit?", [["€ 5.000,00", "Er is voor de helft van de werkelijke waarde verzekerd, dus wordt de schade voor de helft vergoed: € 10.000,00 x 30.000/60.000."], ["€ 10.000,00", "Zonder garantie tegen onderverzekering wordt de schade bij onderverzekering niet volledig vergoed."], ["€ 30.000,00", "Het verzekerde bedrag is een maximum, geen uitkering bij elke schade."], ["€ 3.333,33", "Deze berekening past de verhouding niet juist toe; de verhouding verzekerd/waarde is 1/2."]], "1g.16"],
["In welke box van de inkomstenbelasting valt spaargeld van een particulier?", [["Box 3", "Box 3 belast inkomen uit sparen en beleggen."], ["Box 1", "Box 1 betreft inkomen uit werk en woning, zoals loon en de eigen woning."], ["Box 2", "Box 2 betreft inkomen uit een aanmerkelijk belang in een vennootschap."], ["Spaargeld valt buiten de inkomstenbelasting", "Spaargeld kan in box 3 worden belast, afhankelijk van het vermogen en het heffingvrij vermogen."]], "1a.8"],
["Aan welke aflossingseis moet een nieuwe hypotheeklening voor de eigen woning sinds 2013 in beginsel voldoen om de rente aftrekbaar te laten zijn?", [["De lening moet in maximaal 30 jaar ten minste annuïtair worden afgelost", "Voor nieuwe eigenwoningschulden sinds 1 januari 2013 is renteaftrek gekoppeld aan deze aflossingseis."], ["De lening mag aflossingsvrij zijn als de klant een spaarrekening aanhoudt", "Een nieuwe aflossingsvrije lening voldoet niet aan de aflossingseis voor renteaftrek."], ["De lening moet binnen tien jaar volledig zijn afgelost", "De wet vraagt geen aflossing binnen tien jaar, maar ten minste annuïtair in maximaal 30 jaar."], ["Er geldt geen aflossingseis, zolang de woning de hoofdverblijfplaats is", "Hoofdverblijf is een voorwaarde voor de eigen woning, maar daarnaast geldt de aflossingseis."]], "1c.23"],
["Wat is het verschil tussen een persoonlijke lening en een doorlopend krediet?", [["Persoonlijke lening: vast bedrag en vaste looptijd; doorlopend krediet: binnen een limiet opnemen en terugbetalen", "Dit zijn de kernkenmerken van beide vormen van consumptief krediet."], ["Een persoonlijke lening heeft altijd een variabele rente; een doorlopend krediet heeft juist altijd een vaste rente", "Het is doorgaans andersom: een doorlopend krediet kent meestal een variabele rente."], ["Bij een doorlopend krediet hoeft nooit te worden afgelost", "Ook bij een doorlopend krediet wordt maandelijks een termijn betaald."], ["Een persoonlijke lening wordt niet geregistreerd, een doorlopend krediet wel", "Beide kredietvormen worden in beginsel geregistreerd bij het BKR."]], "1c.5"],
["Wat registreert het Centraal Krediet Informatiesysteem (CKI) van het BKR?", [["Kredieten van consumenten en eventuele betalingsachterstanden daarop", "Kredietverstrekkers raadplegen deze registratie om overkreditering te voorkomen."], ["Het vermogen dat consumenten op hun spaar- en beleggingsrekeningen bij banken hebben", "Spaartegoeden worden niet bij het BKR geregistreerd."], ["Alle verzekeringspolissen van consumenten", "Verzekeringen worden niet in het CKI geregistreerd."], ["Het inkomen van consumenten volgens de Belastingdienst", "Inkomensgegevens maken geen deel uit van het CKI."]], "1a.10"],
["Wat is het verschil tussen een heffingskorting en een aftrekpost in de inkomstenbelasting?", [["Een heffingskorting verlaagt de verschuldigde belasting zelf; een aftrekpost verlaagt het belastbare inkomen", "Een aftrekpost levert voordeel op tegen het tarief, terwijl een heffingskorting direct op de belasting in mindering komt."], ["Een heffingskorting verlaagt het belastbare inkomen; een aftrekpost verlaagt rechtstreeks de verschuldigde belasting zelf", "Dit is precies omgekeerd."], ["Er is geen verschil; beide termen betekenen hetzelfde", "Beide werken op een ander niveau in de belastingberekening."], ["Een heffingskorting geldt alleen voor ondernemers", "Heffingskortingen, zoals de algemene heffingskorting, gelden ook voor particulieren."]], "1a.8"],
["Welke verbintenis heeft een adviseur in de regel op grond van de overeenkomst van opdracht?", [["Een inspanningsverbintenis: hij moet de zorg van een goed opdrachtnemer in acht nemen", "De adviseur belooft zorgvuldig te werken, niet een bepaald resultaat zoals een gegarandeerd rendement."], ["Een resultaatsverbintenis: hij garandeert dat het geadviseerde product het beoogde resultaat oplevert", "Een adviseur garandeert in de regel geen uitkomst; hij moet zorgvuldig handelen."], ["Een verbintenis om alleen te doen wat de klant letterlijk vraagt", "Een goed opdrachtnemer denkt mee en waarschuwt waar nodig."], ["Geen verbintenis, omdat advies vrijblijvend is", "Een adviesopdracht is een overeenkomst waaruit verplichtingen voortvloeien."]], "1f.29"],
["Wat moet een schuldeiser in de regel doen voordat de schuldenaar in verzuim is bij het niet nakomen van een overeenkomst?", [["De schuldenaar in gebreke stellen met een redelijke termijn om alsnog na te komen", "Pas na het verstrijken van die termijn treedt verzuim in, tenzij een uitzondering geldt zoals een fatale termijn."], ["Direct de rechter vragen de overeenkomst te ontbinden", "Ontbinding vraagt in de regel eerst verzuim, en kan ook buitengerechtelijk."], ["De schuldenaar melden bij de AFM", "De AFM speelt geen rol bij de civielrechtelijke nakoming."], ["Niets, verzuim ontstaat altijd automatisch op de dag waarop de afgesproken prestatie had moeten plaatsvinden", "Automatisch verzuim geldt alleen in uitzonderingsgevallen, zoals bij een fatale termijn."]], "1c.8"],
["Wanneer verjaart in de regel een vordering tot schadevergoeding van een klant tegen zijn adviseur?", [["Vijf jaar na bekendheid met schade en aansprakelijke persoon, uiterlijk twintig jaar na de schadeveroorzakende gebeurtenis", "Dit is de hoofdregel in het Burgerlijk Wetboek voor de verjaring van schadevorderingen."], ["Eén jaar na het geven van het advies, ongeacht het moment waarop de klant de schade of de fout ontdekt", "Een termijn van één jaar is niet de hoofdregel voor schadevorderingen."], ["Nooit, een vordering op een adviseur verjaart niet", "Ook vorderingen op adviseurs verjaren."], ["Drie maanden na de eerste klacht bij de adviseur, tenzij de klant binnen die termijn een procedure bij Kifid start", "Deze termijn heeft niets te maken met de civielrechtelijke verjaring."]], "1f.5"],
["Youssef El Amrani (26) sluit via een tussenpersoon een autoverzekering af. Op het aanvraagformulier wordt gevraagd naar schades in de afgelopen vijf jaar. Youssef vult in dat hij geen schades heeft gehad, terwijl hij vorig jaar twee schades heeft geclaimd bij een andere verzekeraar. Hij denkt dat de nieuwe verzekeraar dat toch niet ziet. Wat geldt voor de mededelingsplicht van Youssef?", [["Hij moet feiten melden die hij kent en waarvan hij moet begrijpen dat ze voor de verzekeraar van belang zijn", "Zijn schadeverleden is zo'n feit en er wordt bovendien naar gevraagd. Verzwijgt hij dit, dan kan de verzekeraar bij schade minder of niets uitkeren en bij opzet tot misleiding de verzekering opzeggen."], ["Hij hoeft alleen feiten te melden die de verzekeraar pas na een eerste schademelding bij hem opvraagt", "De mededelingsplicht geldt juist vóór het sluiten van de verzekering."], ["Hij hoeft niets te melden; de verzekeraar moet zijn schadeverleden zelf onderzoeken", "De verzekeraar mag erop vertrouwen dat de klant de gevraagde feiten juist meldt."], ["Hij hoeft alleen schades te melden die bij dezelfde verzekeraar zijn geclaimd", "Ook schades bij een andere verzekeraar zijn van belang voor de beoordeling van het risico."]], "1g.12"],
["Lotte de Graaf (31) sluit op een zondagavond via de website van een verzekeraar een inboedelverzekering af. Ze heeft niemand gesproken en alles digitaal ingevuld. Twee dagen later ziet ze elders een goedkopere polis met een ruimere dekking. Ze wil de net afgesloten verzekering ongedaan maken. Welk recht heeft Lotte in beginsel?", [["Zij kan de overeenkomst binnen 14 dagen zonder opgave van redenen ontbinden", "Bij een financiële dienst die op afstand is gesloten, heeft de consument in beginsel 14 dagen bedenktijd. Lotte zit daar ruim binnen."], ["Zij heeft geen herroepingsrecht, omdat de dekking direct is ingegaan", "Het herroepingsrecht geldt ook als de dekking al is ingegaan."], ["Zij kan alleen op de dag van afsluiten herroepen, daarna niet meer", "De wettelijke bedenktijd is 14 dagen, niet één dag."], ["Zij kan alleen opzeggen tegen het einde van het eerste verzekeringsjaar", "Dankzij het herroepingsrecht hoeft zij niet tot het einde van het contractjaar te wachten."]], "1g.21"],
["Wat geldt voor een beding in algemene voorwaarden dat op de zwarte lijst staat bij een consumentenovereenkomst?", [["Het beding wordt altijd als onredelijk bezwarend aangemerkt en is vernietigbaar", "Bij de zwarte lijst is geen nadere afweging nodig; bij de grijze lijst wordt onredelijkheid slechts vermoed."], ["Het beding wordt vermoed onredelijk bezwarend te zijn, maar tegenbewijs is mogelijk", "Dit is het kenmerk van de grijze lijst."], ["Het beding is altijd geldig, omdat de consument heeft getekend", "Ondertekening maakt een beding op de zwarte lijst niet geldig."], ["Het beding geldt alleen tussen bedrijven, niet tegenover consumenten", "De zwarte lijst is juist bedoeld om consumenten te beschermen."]], "1g.1"],
["Een medewerker van een advieskantoor maakt bij het advies een fout, waardoor de klant schade lijdt. Bij wie kan de klant de schade in de regel verhalen?", [["Bij het advieskantoor, dat contractspartij is en als werkgever aansprakelijk is voor zijn medewerkers", "De klant heeft de overeenkomst met het kantoor gesloten; ook geldt de werkgeversaansprakelijkheid voor fouten van werknemers."], ["Alleen bij de medewerker persoonlijk", "De klant kan in de regel het kantoor aanspreken; persoonlijke aansprakelijkheid van de werknemer is beperkt."], ["Bij de AFM, omdat die toezicht houdt op het kantoor", "De toezichthouder is niet aansprakelijk voor adviesfouten van een kantoor."], ["Bij de aanbieder van het geadviseerde product, omdat die de polis heeft afgegeven en de premie ontvangt", "De aanbieder is niet verantwoordelijk voor fouten van een zelfstandig advieskantoor."]], "1f.35"],
["Welke van de volgende regelingen is een werknemersverzekering?", [["De WIA", "De WIA is een werknemersverzekering bij langdurige arbeidsongeschiktheid, gefinancierd met premies via de werkgever."], ["De AOW", "De AOW is een volksverzekering voor iedereen die in Nederland woont of werkt."], ["De Anw", "De Anw is een volksverzekering voor nabestaanden."], ["De Wet langdurige zorg", "De Wlz is een volksverzekering voor langdurige zorg."]], "1d.7"],
["Karin Boer (45) werkt als verpleegkundige in een ziekenhuis. Na een ernstig ongeluk is zij al een jaar volledig ziek. Haar werkgever betaalt haar loon door en er wordt hard gewerkt aan haar re-integratie. Karin vraagt zich af wanneer ze een WIA-uitkering kan krijgen als ze niet herstelt. Wanneer kan een WIA-uitkering in de regel ingaan?", [["Na 104 weken ziekte", "De WIA kent een wachttijd van 104 weken, waarin de werkgever het loon doorbetaalt. Alleen bij duurzame volledige arbeidsongeschiktheid kan een IVA-uitkering soms eerder ingaan."], ["Na 13 weken ziekte, als de werkgever stopt met doorbetalen", "De werkgever stopt na 13 weken niet; de loondoorbetaling loopt door en een WIA-uitkering volgt nog niet."], ["Direct op de eerste ziektedag", "In de eerste twee jaar betaalt de werkgever het loon door."], ["Na 52 weken ziekte", "Na een jaar ziekte loopt de wachttijd van de WIA nog een jaar door."]], "1d.9"],
["Wanneer heeft iemand recht op een IVA-uitkering binnen de WIA?", [["Als hij volledig en duurzaam arbeidsongeschikt is", "De IVA is bedoeld voor wie geen of nauwelijks kans op herstel heeft en volledig arbeidsongeschikt is."], ["Als hij gedeeltelijk arbeidsongeschikt is en kans op herstel heeft", "In die situatie is de WGA van toepassing, niet de IVA."], ["Als hij minder dan 35% arbeidsongeschikt is", "Bij minder dan 35% arbeidsongeschiktheid is er in beginsel geen recht op een WIA-uitkering."], ["Als hij werkloos is geworden na een reorganisatie", "Werkloosheid valt onder de WW, niet onder de IVA."]], "1d.13"],
["Ahmed Bakkali (50) is magazijnmedewerker en heeft na een hernia twee jaar niet volledig kunnen werken. Bij de WIA-keuring stelt het UWV vast dat hij 25% arbeidsongeschikt is. Hij kan nog ander passend werk doen. Ahmed vraagt wat dit betekent voor een uitkering uit de WIA. Wat geldt in beginsel?", [["Geen recht op een WIA-uitkering, omdat hij minder dan 35% arbeidsongeschikt is", "Bij minder dan 35% arbeidsongeschiktheid bestaat in beginsel geen recht op een WIA-uitkering. Ahmed blijft aangewezen op inkomen uit (ander) werk."], ["Hij krijgt een IVA-uitkering voor de duur van zijn arbeidsongeschiktheid", "De IVA is alleen voor volledig en duurzaam arbeidsongeschikten."], ["Hij krijgt een WGA-uitkering naar rato van zijn arbeidsongeschiktheid van 25%", "De WGA geldt pas vanaf 35% arbeidsongeschiktheid."], ["Hij krijgt tot zijn AOW-leeftijd een aanvulling via de Anw", "De Anw is een nabestaandenregeling en geen regeling bij arbeidsongeschiktheid."]], "1d.9"],
["Dennis Kuipers (34) is drie jaar geleden voor zichzelf begonnen als timmerman. Hij werkt als zzp'er voor verschillende opdrachtgevers en heeft geen personeel. Na een val van een steiger beseft hij dat hij niet weet wat er gebeurt als hij langdurig niet kan werken. Hij vraagt welke wettelijke voorziening hem beschermt. Wat is juist?", [["Als zelfstandige valt hij in beginsel niet onder de WIA en moet hij dit risico zelf afdekken", "De WIA is een werknemersverzekering. Een zzp'er kan het risico bijvoorbeeld afdekken met een arbeidsongeschiktheidsverzekering of een broodfonds."], ["Hij valt automatisch onder de WIA zodra hij bij de KvK staat ingeschreven", "Inschrijving bij de KvK maakt hem geen werknemer; de WIA geldt voor werknemers."], ["Hij krijgt een AOW-uitkering zodra hij arbeidsongeschikt raakt", "De AOW is een ouderdomsvoorziening vanaf de AOW-leeftijd."], ["Hij heeft recht op een WW-uitkering zolang hij niet kan werken", "De WW is een werknemersverzekering bij werkloosheid, niet bij arbeidsongeschiktheid."]], "1d.13"],
["Marloes (48) is weduwe geworden; haar man is plotseling overleden. Ze hebben twee kinderen van 19 en 21 jaar, die nog thuis wonen. Marloes werkt vier dagen per week en is gezond. Ze vraagt of ze een nabestaandenuitkering uit de Anw kan krijgen. Wat is juist?", [["Nee, want zij verzorgt geen kind jonger dan 18 jaar en is niet arbeidsongeschikt", "Een Anw-uitkering is er alleen onder strikte voorwaarden, zoals de zorg voor een kind jonger dan 18 jaar of ten minste 45% arbeidsongeschiktheid. Marloes voldoet daar niet aan."], ["Ja, iedere nabestaande van een overleden echtgenoot heeft recht op Anw tot de AOW-leeftijd", "De Anw kent strikte voorwaarden; lang niet iedere nabestaande heeft recht."], ["Ja, omdat zij ouder is dan 45 jaar en daardoor altijd recht heeft op Anw", "Leeftijd alleen geeft geen recht; die regel geldt alleen voor nabestaanden die vóór 1950 zijn geboren."], ["Ja, maar alleen voor haar kinderen, omdat de Anw aan wezen wordt uitgekeerd", "Een wezenuitkering is er alleen als beide ouders zijn overleden; de kinderen hebben hun moeder nog."]], "1d.6"],
["Hoe bouwt iemand recht op AOW op?", [["Met 2% per jaar dat hij in Nederland woont of werkt in de 50 jaar vóór de AOW-leeftijd", "Wie die volledige periode verzekerd is geweest, heeft recht op een volledige AOW; elk ontbrekend jaar kost 2%."], ["Door per jaar premie te betalen in een individuele pensioenpot die bij de SVB wordt belegd", "De AOW is een omslagstelsel; er wordt geen individuele pot opgebouwd."], ["Alleen via de werkgever bij een pensioenfonds", "Pensioen via de werkgever is de tweede pijler; de AOW is de eerste pijler."], ["Met 1% per jaar dat iemand in loondienst heeft gewerkt", "De opbouw hangt af van wonen of werken in Nederland, niet alleen van loondienst, en bedraagt 2% per jaar."]], "1d.8"],
["Wat is volgens de SFDR het verschil tussen een artikel 8- en een artikel 9-product?", [["Een artikel 8-product promoot ecologische of sociale kenmerken; een artikel 9-product heeft duurzame beleggingen als doelstelling", "Artikel 9-producten hebben duurzaamheid als expliciet doel en worden vaak als donkergroen aangeduid."], ["Een artikel 8-product heeft duurzame beleggingen als doelstelling; een artikel 9-product promoot alleen ecologische of sociale kenmerken", "Dit is precies omgekeerd."], ["Een artikel 8-product is altijd een spaarproduct; een artikel 9-product altijd een aandelenfonds", "De artikelen gaan over duurzaamheidsambitie, niet over het soort product."], ["Er is geen verschil; beide artikelen gelden voor alle beleggingsfondsen", "De artikelen onderscheiden juist producten met een verschillend duurzaamheidsprofiel."]], "1b.17"],
["Wat is een duurzaamheidsrisico in de zin van de SFDR?", [["Een ecologische, sociale of governancegebeurtenis of -omstandigheid die de waarde van een belegging wezenlijk negatief kan beïnvloeden", "Het gaat om het risico dat duurzaamheidsfactoren de waarde van de belegging raken."], ["Het risico dat een duurzame belegging over een periode van vijf jaar minder rendement oplevert dan de gemiddelde markt", "Een lager rendement op zich is geen duurzaamheidsrisico in de zin van de SFDR."], ["Het risico dat een klant geen duurzaamheidsvoorkeuren heeft", "Klantvoorkeuren zijn een ander begrip dan het duurzaamheidsrisico van een belegging."], ["Het risico dat de AFM een product als niet duurzaam beoordeelt", "De SFDR omschrijft het risico vanuit de belegging, niet vanuit de toezichthouder."]], "1b.17"],
["Bij welke dienstverlening moet een adviseur in beginsel vragen naar de duurzaamheidsvoorkeuren van de klant?", [["Bij advies over verzekeringsgebaseerde beleggingsproducten en bij beleggingsadvies", "Sinds 2 augustus 2022 maken duurzaamheidsvoorkeuren deel uit van de geschiktheidsbeoordeling bij deze vormen van advies."], ["Bij iedere schadeverzekering, zoals een autoverzekering", "Voor gewone schadeverzekeringen geldt deze uitvraag niet."], ["Alleen bij zakelijke klanten met meer dan vijftig werknemers die onder de rapportageplicht van de CSRD vallen", "De uitvraag geldt juist bij advies aan klanten, ongeacht een werknemersaantal."], ["Nooit; het vragen naar duurzaamheid is volledig vrijwillig", "Bij de genoemde vormen van advies is het een verplicht onderdeel."]], "1f.15"],
["Welke indeling van duurzaamheidsvoorkeuren hanteert de Europese regelgeving bij advies?", [["Minimumaandeel taxonomieconforme beleggingen, minimumaandeel duurzame beleggingen (SFDR) en aandacht voor de belangrijkste ongunstige effecten", "Een klant kan een of meer van deze voorkeuren aangeven, die de adviseur meeneemt in zijn advies."], ["Een voorkeur voor een laag, middel of hoog rendement", "Rendementswens hoort bij de doelstellingen van de klant, niet bij de duurzaamheidsvoorkeuren."], ["Een voorkeur voor Nederlandse, Europese of wereldwijde beleggingen", "Een regionale voorkeur is geen wettelijke categorie van duurzaamheidsvoorkeuren."], ["Een voorkeur voor groen, oranje of rood volgens het AFM-duurzaamheidslabel, aangevuld met een minimale ESG-score per fonds", "Er bestaat geen wettelijk AFM-kleurenlabel voor duurzaamheidsvoorkeuren."]], "1f.15"],
["Een adviseur presenteert een beleggingsverzekering als 'volledig groen', terwijl de aanbieder het product niet als duurzaam classificeert en er geen onderbouwing is. Wat is juist?", [["Dit is greenwashing: misleidende informatie, in strijd met de eis dat informatie correct, duidelijk en niet misleidend is", "Duurzaamheidsclaims moeten kloppen en onderbouwd zijn, net als andere productinformatie."], ["Dit is toegestaan, omdat duurzaamheid een subjectief begrip is", "Ook duurzaamheidsclaims moeten feitelijk juist en onderbouwd zijn."], ["Dit is toegestaan als de klant geen duurzaamheidsvoorkeuren heeft, omdat duurzaamheid dan geen rol speelt in het advies", "Ook tegenover een klant zonder voorkeuren mag informatie niet misleidend zijn."], ["Dit is alleen een probleem als de AFM het product vooraf heeft gekeurd", "De AFM keurt producten niet vooraf; de informatieplicht geldt altijd."]], "4a.4"],
["Een klant geeft bij een beleggingsadvies aan geen duurzaamheidsvoorkeuren te hebben. Wat is juist?", [["De adviseur legt dit vast; hij mag dan zowel producten met als zonder duurzame kenmerken adviseren", "Een klant zonder voorkeuren wordt als duurzaamheidsneutraal behandeld; het advies moet verder gewoon passend zijn."], ["De adviseur mag dan alleen producten zonder enig duurzaam kenmerk adviseren, zoals een artikel 6-product", "Ook producten met duurzame kenmerken mogen worden geadviseerd aan een klant zonder voorkeuren."], ["De adviseur mag de klant dan geen advies meer geven", "Het ontbreken van voorkeuren staat advies niet in de weg."], ["De adviseur moet de klant verplichten toch een voorkeur te kiezen", "Het aangeven van voorkeuren is een keuze van de klant, geen verplichting."]], "1f.15"],
["Ingrid spaart elke maand € 150,00, omdat ze over drie jaar een wereldreis wil maken. Welk spaarmotief hoort hierbij?", [["Het doelmotief", "Ingrid spaart voor een concreet doel op een bepaald moment: de wereldreis."], ["Het zekerheidsmotief", "Bij het zekerheidsmotief spaart iemand een buffer voor onverwachte uitgaven, zoals een kapotte wasmachine."], ["Het vermogensmotief", "Bij het vermogensmotief spaart iemand om vermogen op te bouwen, zonder concreet bestedingsdoel."], ["Het transactiemotief", "Dit is geen van de drie spaarmotieven; het gaat over geld aanhouden voor dagelijkse betalingen."]], "1b.6"],
["Waarom trekt een bank spaargeld van consumenten aan?", [["Omdat spaargeld een relatief goedkope financieringsbron is voor de kredieten die de bank verstrekt", "De bank gebruikt het spaargeld om bijvoorbeeld hypotheken te verstrekken. Het verschil tussen de ontvangen en de betaalde rente is een belangrijke bron van inkomsten."], ["Omdat de bank wettelijk verplicht is voor iedere klant een spaarrekening aan te houden", "Er bestaat geen wettelijke plicht om iedere klant een spaarrekening te geven."], ["Omdat spaargeld niet op de balans van de bank staat en dus geen risico oplevert", "Spaargeld is een schuld van de bank aan de spaarder en staat juist op de balans."], ["Omdat de bank over spaargeld nooit rente hoeft te vergoeden aan de spaarder", "De bank vergoedt wel rente; ze verdient aan het verschil met de rente op kredieten."]], "1b.7"],
["Bakker Kees koopt voor zijn bakkerij een nieuwe oven om meer brood te kunnen bakken. Zijn buurvrouw koopt aandelen in een beursfonds en zijn zoon zet geld op een spaarrekening. Welke uitspraak is juist?", [["Kees investeert, de buurvrouw belegt en de zoon spaart", "Investeren is geld besteden aan productiemiddelen zoals een oven. Beleggen is vermogen inzetten voor rendement met meer risico; sparen is geld veilig opzij zetten."], ["Kees belegt, de buurvrouw investeert en de zoon spaart", "Een oven voor het eigen bedrijf is een investering, geen belegging."], ["Alle drie beleggen, omdat ze allemaal geld voor later opzij zetten", "Sparen, beleggen en investeren verschillen in doel en risico."], ["Kees spaart, omdat de oven later weer verkocht kan worden", "Het kopen van een productiemiddel is investeren, ook als het later wordt verkocht."]], "1b.10"],
["De AFM stelt vast dat een dagelijks beleidsbepaler van een advieskantoor niet langer betrouwbaar is. Het kantoor onderneemt niets. Welke maatregel staat de AFM onder meer ter beschikking?", [["Zij kan uiteindelijk de vergunning van het kantoor intrekken", "Wie niet meer aan de vergunningseisen voldoet, kan zijn vergunning verliezen; intrekking is een van de zwaarste maatregelen van de AFM."], ["Zij kan de beleidsbepaler zelf een gevangenisstraf opleggen", "Vrijheidsstraffen legt alleen de strafrechter op, na vervolging door het Openbaar Ministerie."], ["Zij kan het kantoor verplichten zijn aansluiting bij Kifid te beëindigen", "Aansluiting bij Kifid is juist verplicht voor dienstverlening aan consumenten; beëindigen is geen toezichtmaatregel."], ["Zij moet eerst een uitspraak van Kifid afwachten voordat zij mag optreden", "De AFM handhaaft zelfstandig en is niet afhankelijk van een geschilprocedure bij Kifid."]], "1f.25"],
["Wat is een aangesloten onderneming in de zin van de Wft?", [["Een onderneming zonder eigen vergunning die werkt onder verantwoordelijkheid van een serviceprovider met vergunning", "De serviceprovider heeft een vergunning en staat ervoor in dat de aangesloten onderneming de Wft-regels naleeft."], ["Een onderneming die bij Kifid is aangesloten en daardoor geen eigen AFM-vergunning meer nodig heeft voor haar diensten", "Aansluiting bij Kifid gaat over klachtbehandeling en vervangt de vergunningplicht niet."], ["Een onderneming die lid is van een brancheorganisatie en daardoor onder het toezicht van die organisatie valt", "Een brancheorganisatie is geen toezichthouder; het begrip gaat over werken onder de vergunning van een ander."], ["Een dochtermaatschappij van een bank die automatisch onder het prudentiële toezicht van DNB valt", "Dat beschrijft een groepsrelatie, niet het Wft-begrip aangesloten onderneming."]], "1f.38"],
["Welke verzekering moet een adviseur of bemiddelaar met een Wft-vergunning in beginsel hebben?", [["Een beroepsaansprakelijkheidsverzekering", "Die dekt schade die klanten lijden door beroepsfouten; zo'n verzekering is een vergunningseis voor adviseurs en bemiddelaars."], ["Een rechtsbijstandverzekering voor zakelijke geschillen", "Die kan nuttig zijn voor het kantoor, maar is geen wettelijke vergunningseis."], ["Een kredietverzekering voor onbetaalde facturen van klanten", "Die beschermt het kantoor tegen wanbetaling, niet de klant tegen adviesfouten."], ["Een bedrijfsschadeverzekering voor omzetverlies na brand", "Die dekt een bedrijfsrisico van het kantoor zelf en is niet verplicht voor de vergunning."]], "1f.35"],
["Esther Wouters (45) werkt sinds tien jaar als zelfstandig grafisch ontwerper en bouwt geen pensioen op via een werkgever. Ze heeft jaarruimte en opent bij haar bank een lijfrentespaarrekening. Ze stort daar dit jaar € 5.000,00 op. Ze vraagt wat de fiscale gevolgen zijn. Wat is juist?", [["Haar inleg is binnen haar jaarruimte aftrekbaar in box 1; de latere uitkeringen zijn in box 1 belast", "Bij lijfrentebanksparen is de inleg binnen de jaar- of reserveringsruimte aftrekbaar. Daartegenover worden de uitkeringen later in box 1 belast; het tegoed valt tijdens de opbouw niet in box 3."], ["Haar inleg is niet aftrekbaar, maar de latere uitkeringen zijn volledig belastingvrij", "Het is andersom: de inleg is aftrekbaar en de uitkeringen zijn belast."], ["Haar tegoed valt elk jaar in box 3 en de inleg is aftrekbaar in box 2", "Een lijfrentetegoed valt niet in box 3, en box 2 gaat over aanmerkelijk belang."], ["Ze kan het tegoed op elk moment zonder fiscale gevolgen opnemen als gewoon spaargeld", "Het tegoed is geblokkeerd; eerder opnemen leidt tot belastingheffing en kan revisierente kosten."]], "1b.13"],
["Wat onderscheidt een gevolmachtigd agent van een gewone verzekeringsbemiddelaar?", [["Hij mag op grond van een volmacht namens de verzekeraar verzekeringen sluiten", "De verzekeraar heeft hem bevoegd gemaakt om namens haar te handelen, vaak ook bij premie-inning en schadebehandeling."], ["Hij werkt uitsluitend voor particuliere klanten en nooit voor zakelijke klanten", "Het onderscheid gaat over bevoegdheden namens de verzekeraar, niet over de doelgroep."], ["Hij heeft geen Wft-vergunning nodig, omdat hij namens de verzekeraar optreedt", "Ook een gevolmachtigd agent valt onder de Wft en heeft in beginsel een vergunning nodig."], ["Hij mag alleen adviseren en mag nooit zelf een verzekering tot stand brengen", "Het is juist andersom: kenmerkend is dat hij namens de verzekeraar mag sluiten."]], "1g.2"],
["Een kantoor met een AFM-vergunning voor schadeverzekeringen wil ook gaan adviseren over hypothecair krediet. Wat moet het kantoor doen?", [["De vergunning laten uitbreiden met hypothecair krediet en zorgen voor vakbekwaamheid", "Een vergunning geldt voor de producten die erin zijn vermeld; voor een nieuw productgebied zijn uitbreiding en passende vakbekwaamheid nodig."], ["Niets, want één Wft-vergunning geldt automatisch voor alle soorten financiële producten", "De vergunning vermeldt voor welke financiële producten zij geldt; andere producten vallen er niet onder."], ["Alleen bij Kifid melden dat het kantoor voortaan ook hypotheekklachten kan krijgen", "Kifid behandelt geschillen en verleent geen vergunningen."], ["Alleen de inschrijving bij de Kamer van Koophandel aanpassen met de nieuwe activiteit", "Een KvK-inschrijving staat los van de vergunningplicht bij de AFM."]], "1f.25"],
["Een advieskantoor wil een nieuwe directeur benoemen die het dagelijks beleid gaat bepalen. Wat geldt?", [["De AFM toetst zijn betrouwbaarheid en geschiktheid, in beginsel vooraf", "Een nieuwe dagelijks beleidsbepaler moet vooraf bij de AFM worden aangemeld en getoetst."], ["De benoeming hoeft pas achteraf in het jaarverslag te worden vermeld", "Achteraf is te laat: de toetsing vindt in beginsel plaats voordat de beleidsbepaler begint."], ["Een toets is alleen nodig als de directeur ook zelf klanten gaat adviseren", "De toets hangt samen met het bepalen van het beleid, niet met het zelf adviseren."], ["De Kamer van Koophandel beoordeelt of de nieuwe directeur betrouwbaar is", "De KvK registreert bestuurders, maar de toetsing op betrouwbaarheid en geschiktheid ligt bij de AFM."]], "1f.33"],
["Een medewerker van een advieskantoor verwerkt alleen polismutaties in de administratie en heeft geen contact met klanten over financiële producten. Moet hij een Wft-diploma hebben?", [["Nee, de vakbekwaamheidseisen zijn gekoppeld aan werkzaamheden met klantcontact over advies of bemiddeling", "Zuiver administratieve taken zonder klantcontact over financiële producten vallen buiten de diplomaplicht."], ["Ja, iedere medewerker van een vergunninghouder moet ten minste Wft Basis hebben behaald", "De eis hangt af van de werkzaamheden, niet van het enkele feit dat iemand bij een vergunninghouder werkt."], ["Ja, omdat hij bij zijn werk persoonsgegevens van klanten verwerkt en daarvoor vakbekwaam moet zijn op grond van de Wft", "Het verwerken van persoonsgegevens valt onder de AVG, niet onder de Wft-vakbekwaamheidseisen."], ["Alleen als hij langer dan een jaar bij het kantoor in dienst is", "De duur van het dienstverband bepaalt niet of een diploma nodig is."]], "1f.33"],
["Adviseur Jasper heeft de diploma's Wft Basis en Wft Schadeverzekeringen Particulier. Hij regelt al jaren de verzekeringen van de familie Willems. Nu wil het gezin verhuizen en vraagt het Jasper ook het hypotheekadvies te verzorgen. Het kantoor heeft wel een vergunning voor hypothecair krediet. Wat is juist?", [["Hij mag dat pas doen als hij ook voor hypothecair krediet vakbekwaam is; tot die tijd verwijst hij door", "Vakbekwaamheid geldt per productgebied. Jasper kent de grenzen van zijn deskundigheid en brengt de familie in contact met een vakbekwame collega."], ["Hij mag adviseren, omdat Wft Basis de algemene kennis voor alle productgebieden dekt", "Wft Basis is niet voldoende; voor hypotheekadvies is ook de module Hypothecair krediet nodig."], ["Hij mag adviseren, omdat het kantoor een vergunning voor hypothecair krediet heeft", "De vergunning van het kantoor ontslaat de adviseur niet van zijn eigen vakbekwaamheidseisen."], ["Hij mag adviseren als de familie schriftelijk verklaart daarmee akkoord te gaan", "Vakbekwaamheidseisen zijn wettelijk en kunnen niet door de klant opzij worden gezet."]], "4a.2"],
["Een nieuwe medewerker heeft zijn Wft-diploma nog niet gehaald, maar wil al meewerken aan adviestrajecten. Wat is in beginsel mogelijk?", [["Tijdelijk werken onder begeleiding van een vakbekwame collega terwijl hij zijn diploma haalt", "De regels staan werken onder begeleiding voor een beperkte periode toe, mits een vakbekwame begeleider toezicht houdt en verantwoordelijk is."], ["Zelfstandig adviseren, zolang de klant niet weet dat hij nog in opleiding is", "Zelfstandig adviseren zonder vakbekwaamheid is niet toegestaan, ongeacht wat de klant weet."], ["Niets: zonder diploma mag hij zelfs niet bij een adviesgesprek aanwezig zijn", "Aanwezig zijn en onder begeleiding meewerken is wel mogelijk."], ["Zelfstandig adviseren zodra hij een aanvraag tot gelijkstelling van een oud diploma heeft ingediend", "Een ingediende aanvraag is nog geen erkende vakbekwaamheid."]], "1f.33"],
["De vader van Jolanda en Marco is overleden. In zijn testament is Jolanda benoemd tot executeur. Er moeten nog rekeningen worden betaald, zoals de uitvaart en de laatste huur. Jolanda vraagt bij de bank of er een aparte rekening kan worden geopend om de nalatenschap af te wikkelen. Wat is juist over een boedelrekening?", [["Het is een rekening op naam van de nalatenschap, die Jolanda als executeur kan openen voor de afwikkeling", "Op een boedelrekening komen de tegoeden van de overledene en worden de schulden van de nalatenschap betaald. Zij kan worden geopend door de executeur of anders door de erfgenamen samen."], ["Het is een rekening op naam van Jolanda privé, waarop de erfenis direct haar eigendom wordt", "Een boedelrekening staat op naam van de nalatenschap; het geld is nog niet van een erfgenaam."], ["Een boedelrekening kan alleen worden geopend door de notaris, nooit door een erfgenaam", "Ook de executeur of de gezamenlijke erfgenamen kunnen een boedelrekening openen."], ["Een boedelrekening is alleen nodig als de erfgenamen de nalatenschap verwerpen", "Een boedelrekening dient voor de afwikkeling van de nalatenschap, ook als de erfgenamen aanvaarden."]], "1b.22"],
["Welke informatie moet een adviseur in elk geval over de klant inwinnen om passend te kunnen adviseren?", [["Financiële positie, kennis en ervaring, doelstellingen en risicobereidheid", "Deze ken-uw-klantgegevens vormen de basis voor een advies dat past bij de situatie van de klant."], ["Alleen het bruto jaarinkomen en de maandlast die de klant zelf wenst te betalen", "Dat is te beperkt; ook kennis, ervaring, doelen en risicobereidheid zijn nodig voor passend advies."], ["De voorkeur van de klant voor een bepaalde aanbieder en zijn burgerlijke staat", "Dat kan nuttig zijn, maar het vormt niet de kern van de informatie die voor passend advies nodig is."], ["Uitsluitend wat de klant uit zichzelf vertelt, want doorvragen is niet toegestaan", "De adviseur moet juist actief doorvragen om een volledig beeld te krijgen."]], "1d.1"],
["Mevrouw Smit (84) is sinds een half jaar weduwe. Haar adviseur bespreekt met haar een voorstel om een deel van haar spaargeld in een beleggingsverzekering onder te brengen. Tijdens het gesprek stelt ze steeds dezelfde vragen en lijkt ze de gevolgen niet goed te overzien. Ze zegt dat ze het wel goed vindt, als de adviseur het zegt. Wat is de beste handelwijze?", [["Extra zorg betrachten, nagaan of zij het echt begrijpt en zo nodig een vertrouwenspersoon betrekken", "Bij een kwetsbare klant past extra zorgvuldigheid. De adviseur moet zeker weten dat mevrouw Smit de gevolgen overziet, eventueel met hulp van iemand die zij vertrouwt."], ["Het advies gewoon afronden, want een meerderjarige klant is zelf verantwoordelijk voor zijn keuzes", "De zorgplicht vraagt meer als de klant de gevolgen kennelijk niet overziet."], ["Direct de AFM vragen te beoordelen of mevrouw Smit nog wilsbekwaam is", "De AFM beoordeelt geen individuele klanten op wilsbekwaamheid."], ["Haar kinderen bellen en het advies zonder haar met hen afronden", "De klant is mevrouw Smit zelf; zonder haar toestemming deel je geen gegevens en beslissen anderen niet voor haar."]], "4a.1"],
["Welke toets moet een beleggingsonderneming doen als een niet-professionele klant zonder advies een complex beleggingsproduct wil kopen?", [["Een passendheidstoets naar kennis en ervaring van de klant", "Onder MiFID II moet de onderneming bij complexe producten zonder advies nagaan of de klant de risico's kan begrijpen en zo nodig waarschuwen."], ["Een geschiktheidstoets naar financiële positie, doelen en risicobereidheid", "Die uitgebreidere toets hoort bij beleggingsadvies en vermogensbeheer, niet bij dienstverlening zonder advies."], ["Geen enkele toets, omdat de klant zelf voor het product kiest", "Ook zonder advies geldt bij complexe producten een passendheidstoets."], ["Een kredietwaardigheidstoets met een raadpleging van het BKR", "Een kredietwaardigheidstoets hoort bij kredietverlening, niet bij het kopen van beleggingen."]], "1f.32"],
["Waarom wint een kredietaanbieder vóór het verstrekken van consumptief krediet informatie in over de financiële positie van de consument?", [["Om overkreditering te voorkomen", "De kredietwaardigheidstoets moet voorkomen dat de consument een krediet krijgt dat hij niet verantwoord kan terugbetalen."], ["Om de hoogte van de vergoeding voor de bemiddelaar te bepalen", "De beloning van een bemiddelaar staat los van het doel van de kredietwaardigheidstoets."], ["Om de rente toe te passen die de AFM voor deze consument voorschrijft", "De AFM schrijft geen rente per consument voor."], ["Om de gegevens te kunnen delen met andere kredietaanbieders voor marketing", "Gebruik voor marketing is een ander doel waarvoor een eigen grondslag nodig is; het is geen doel van de toets."]], "1c.17"],
["Gerard Hoekstra (55) heeft sinds 2005 een levensverzekering met een vaste premie. Zijn adviseur ziet bij een andere verzekeraar een vergelijkbare polis met een lagere premie. Hij overweegt Gerard te adviseren de oude polis af te kopen en de nieuwe te sluiten. Gerard heeft inmiddels wel last van hoge bloeddruk. Waar moet de adviseur in het bijzonder op letten?", [["Of overstappen per saldo gunstig is, gelet op afkoopkosten, nieuwe kosten, acceptatie en verlies van rechten", "Oversluiten kan nadelig zijn door afkoopkosten, nieuwe kosten en een nieuwe medische acceptatie. Met zijn hoge bloeddruk kan Gerard bovendien een hogere premie of een weigering krijgen."], ["Alleen of de premie van de nieuwe polis lager is dan die van zijn huidige polis", "Een lagere premie zegt niets over de totale kosten, de voorwaarden en de acceptatie."], ["Of de huidige verzekeraar vooraf schriftelijk toestemming geeft om de oude polis te beëindigen", "Daar gaat het niet om: de adviseur moet beoordelen of overstappen voor Gerard per saldo gunstig is."], ["Nergens bijzonders, want een nieuwe polis is moderner en daardoor beter", "Nieuwer is niet automatisch beter; vooral kosten en acceptatie kunnen nadelig uitpakken."]], "4a.4"],
["Een klant laat zich adviseren via een online adviestool, zonder persoonlijk contact met een adviseur. Wat geldt voor de zorgplicht?", [["Die geldt onverkort: ook geautomatiseerd advies moet passend zijn", "De onderneming moet ook bij geautomatiseerd advies voldoende klantinformatie inwinnen en een passend advies geven."], ["Die geldt niet, omdat er geen mens bij het advies betrokken is", "Het ontbreken van een menselijke adviseur maakt het niet minder advies."], ["Die geldt pas zodra de klant achteraf een klacht indient", "De zorgplicht geldt bij elk advies vooraf, niet pas wanneer er een klacht komt."], ["Die gaat volledig over op de leverancier die de adviessoftware heeft gebouwd", "De financiële onderneming blijft verantwoordelijk voor het advies dat zij via haar tool geeft."]], "1f.18"],
["Een verzekeraar heeft een product ontwikkeld voor jonge gezinnen met een stabiel inkomen. Een adviseur overweegt het aan een gepensioneerde alleenstaande te adviseren. Wat is juist?", [["Hij moet kritisch nagaan of het past, want de klant valt buiten de doelgroep", "De doelgroep uit het productontwikkelingsproces is bedoeld voor de distributeur; adviseren buiten de doelgroep vraagt een goede onderbouwing."], ["De doelgroep is intern beleid van de verzekeraar en speelt voor de adviseur geen enkele rol", "Distributeurs moeten de doelgroepinformatie van de aanbieder juist meewegen bij hun dienstverlening."], ["Hij mag het product alleen adviseren als de verzekeraar daar schriftelijk toestemming voor geeft", "Toestemming van de verzekeraar is niet de maatstaf; het gaat om de vraag of het product bij de klant past."], ["De klant moet zelf nagaan of hij tot de doelgroep van het product behoort", "Het bewaken van de doelgroep is een taak van aanbieder en adviseur, niet van de klant."]], "1f.15"],
["Een adviseur adviseert over hypotheken met het aanbod van een beperkt aantal geldverstrekkers. Wat moet hij de klant vooraf duidelijk maken?", [["Op basis van welk aanbod hij adviseert", "De klant moet weten dat niet de hele markt wordt vergeleken, zodat hij het advies op waarde kan schatten."], ["Niets, zolang hij het beste product uit zijn eigen selectie adviseert", "Ook dan moet de klant weten dat het aanbod waarop het advies berust beperkt is."], ["Dat hij onafhankelijk is, omdat hij zelf geen financiële producten aanbiedt", "Zonder analyse van voldoende producten op de markt mag hij zich niet onafhankelijk noemen."], ["Dat de klant zelf de overige geldverstrekkers moet benaderen voor een vergelijking", "Zo'n verplichting voor de klant bestaat niet; de adviseur moet wel open zijn over zijn aanbod."]], "1f.37"],
["In een advertentie voor een beleggingsproduct staat het mogelijke rendement groot afgedrukt, terwijl de risico's alleen in kleine letters onderaan staan. Wat is juist?", [["Dit is misleidend: voordelen en risico's moeten evenwichtig worden gepresenteerd", "Informatie, ook in reclame, moet correct, duidelijk en niet misleidend zijn; risico's mogen niet worden weggestopt."], ["Dit is toegestaan, zolang de risico's maar ergens in de advertentie te vinden zijn", "Het wegstoppen van risico's maakt de boodschap als geheel misleidend."], ["Dit is alleen een probleem als een klant het product daadwerkelijk koopt", "De norm geldt voor de informatie zelf, ongeacht of er een aankoop volgt."], ["Dit mag, omdat reclame niet onder de informatieregels van de Wft valt", "Ook reclame-uitingen moeten voldoen aan de Wft-eisen voor informatie aan klanten."]], "1f.15"],
["Wat is het essentiële-informatiedocument (EID) onder de PRIIPs-verordening?", [["Een beknopt standaarddocument over kenmerken, risico's en kosten van verpakte beleggingsproducten", "Het EID moet een niet-professionele belegger vóór aankoop in staat stellen producten te begrijpen en te vergelijken."], ["Het gestandaardiseerde informatieblad over dekking en uitsluitingen dat bij een schadeverzekering hoort", "Dat is het informatiedocument over het verzekeringsproduct (IPID) onder de IDD."], ["Het Europese gestandaardiseerde informatieblad dat bij een hypotheekofferte hoort", "Dat is het ESIS onder de hypothekenrichtlijn."], ["Het jaarlijkse overzicht van de opgebouwde aanspraken bij een pensioenuitvoerder", "Dat is het Uniform Pensioenoverzicht, dat niets met PRIIPs te maken heeft."]], "1f.2"],
["Wat moet een beleggingsadviseur onder MiFID II aan een niet-professionele klant verstrekken voordat een geadviseerde transactie wordt uitgevoerd?", [["Een geschiktheidsverklaring waarin staat waarom het advies bij de klant past", "Die verklaring laat zien hoe het advies aansluit op de situatie, doelen en voorkeuren van de klant en maakt het controleerbaar."], ["Alleen een factuur voor de adviesvergoeding van het kantoor", "Een factuur zegt niets over de onderbouwing van het advies."], ["Een kopie van de vergunning die de AFM aan de beleggingsonderneming heeft verleend", "De vergunningstatus is in het openbare register te raadplegen; het gaat hier om de onderbouwing van het advies."], ["Een schriftelijke verklaring dat het verwachte rendement gegarandeerd is", "Rendement op beleggingen kan niet worden gegarandeerd; zo'n verklaring zou misleidend zijn."]], "1f.32"],
["Een kantoor wil verplichte precontractuele informatie alleen op een webpagina zetten die het op elk moment kan aanpassen. Waarom voldoet dat in de regel niet aan de eis van een duurzame gegevensdrager?", [["Omdat de klant de informatie dan niet zelf kan bewaren en later ongewijzigd kan raadplegen", "Een duurzame drager, zoals een pdf per e-mail, laat de klant de informatie opslaan en ongewijzigd terugzien."], ["Omdat precontractuele informatie aan klanten volgens de Wft altijd op papier moet worden verstrekt", "Digitale verstrekking is toegestaan, mits op een duurzame drager zoals een pdf-bestand."], ["Omdat een webpagina pas geldt als de AFM de tekst vooraf heeft goedgekeurd", "De AFM keurt informatie van ondernemingen niet vooraf goed."], ["Omdat de klant voor het lezen van een webpagina een account moet aanmaken", "Het probleem is niet de toegang maar dat de inhoud kan worden gewijzigd en niet door de klant wordt bewaard."]], "1f.3"],
["Wat laat een overzicht van de cumulatieve kosten van een beleggingsproduct de klant vooral zien?", [["Hoeveel de kosten samen het rendement drukken", "Kosten verlagen het rendement elk jaar opnieuw; het overzicht maakt dit gezamenlijke effect zichtbaar."], ["Hoeveel provisie de adviseur van de aanbieder ontvangt", "Bij beleggingsdienstverlening aan particulieren geldt een provisieverbod; het overzicht gaat over de kosten voor de klant."], ["Welke rendementen het product in het verleden heeft behaald", "Historisch rendement is iets anders dan het effect van kosten op het rendement."], ["Hoe groot de kans is dat de belegging in waarde daalt", "Dat is risico-informatie; het kostenoverzicht gaat over de invloed van kosten."]], "1f.3"],
["Bas koopt in een elektronicawinkel een televisie van € 1.200,00 en betaalt die in termijnen aan de winkel af. Hij krijgt het toestel direct mee, maar ontvangt geen geld. Om welke vorm van krediet gaat het?", [["Een goederenkrediet", "Bij een goederenkrediet krijgt de consument een goed waarvan hij de prijs in termijnen betaalt. Er wordt geen geld aan hem uitgekeerd."], ["Een geldkrediet", "Bij een geldkrediet krijgt de consument een geldbedrag dat hij kan besteden."], ["Een rekening-courantkrediet", "Dat is roodstaan op een betaalrekening tot een afgesproken limiet."], ["Een hypothecair krediet", "Een hypothecair krediet is een lening met een recht van hypotheek op een registergoed als zekerheid."]], "1c.4"],
["Wat zijn passende maatregelen om belangenconflicten binnen een advieskantoor te beheersen?", [["Functiescheiding, een beloningsbeleid zonder verkoopprikkels en registratie van giften en nevenfuncties", "Zulke organisatorische maatregelen verkleinen de kans dat eigen belangen het advies beïnvloeden."], ["Medewerkers vragen belangenconflicten voor zich te houden om klanten niet onnodig te verontrusten of af te schrikken", "Verzwijgen beheerst niets; belangenconflicten moeten juist worden geïdentificeerd en aangepakt."], ["Alle klanten vooraf laten tekenen dat zij afzien van bescherming tegen belangenconflicten", "Een klant kan niet bij voorbaat afstand doen van de wettelijke bescherming; de onderneming moet zelf maatregelen nemen."], ["Steeds de aanbieder adviseren die het kantoor de meeste omzet oplevert, zodat er geen twijfel is", "Dat is precies het belangenconflict dat moet worden voorkomen."]], "1f.33"],
["Geldt ook bij beleggingsadvies en vermogensbeheer voor niet-professionele beleggers een verbod op provisies van aanbieders?", [["Ja, ook dan mogen in beginsel geen provisies van aanbieders worden aangenomen", "Voor beleggingsdienstverlening aan particulieren geldt een vergelijkbaar verbod als het provisieverbod bij complexe producten."], ["Nee, het provisieverbod geldt uitsluitend bij hypothecair krediet", "Het provisieverbod en het verbod bij beleggingsdienstverlening reiken verder dan alleen hypotheken."], ["Nee, provisie is toegestaan zolang de adviseur het bedrag vooraf aan de klant meldt", "Alleen melden is niet genoeg; voor deze diensten geldt een verbod."], ["Alleen bij vermogensbeheer, niet bij beleggingsadvies", "Het verbod geldt voor beide vormen van beleggingsdienstverlening."]], "1f.8"],
["Een bemiddelaar in particuliere schadeverzekeringen ontvangt provisie van de verzekeraar. Wat moet hij de klant onder de IDD in elk geval vertellen?", [["Wat de aard van zijn beloning is", "De klant moet weten hoe de bemiddelaar wordt betaald, bijvoorbeeld via provisie die in de premie is opgenomen, om het advies te kunnen beoordelen."], ["Niets, omdat provisie bij schadeverzekeringen is toegestaan", "Provisie mag hier, maar transparantie over de aard van de beloning blijft verplicht."], ["Hoeveel hij in totaal per jaar aan provisie verdient", "Het totale jaarinkomen van de bemiddelaar hoeft hij niet te melden; het gaat om de aard van de beloning bij dit product."], ["Dat de klant de provisie altijd apart moet voldoen", "Bij schadeverzekeringen zit de provisie juist meestal in de premie."]], "1f.7"],
["Een verzekeraar bezit een aanzienlijk deel van de aandelen van een advieskantoor. Wat moet het kantoor in dit verband doen?", [["De klant vooraf informeren over deze kapitaalrelatie met de verzekeraar", "Een kapitaalbelang kan het advies beïnvloeden; daarom moet de klant ervan op de hoogte zijn."], ["Niets, want eigendomsverhoudingen van het kantoor zijn vertrouwelijke bedrijfsinformatie", "Juist zulke verhoudingen moet de klant kennen om de onafhankelijkheid van het advies te beoordelen."], ["Voortaan uitsluitend producten van deze verzekeraar adviseren aan alle klanten", "Het belang verplicht daar niet toe; het moet transparant worden gemaakt en worden beheerst."], ["De verzekeraar laten beslissen welke klanten het kantoor wel en niet aanneemt", "Dat zou het belangenconflict vergroten in plaats van beheersen."]], "1f.36"],
["Monique Dekker heeft voor het echtpaar Van Leeuwen een ingewikkelde hypotheek- en verzekeringskwestie na een verbouwing opgelost. Het echtpaar is erg tevreden. Bij het laatste gesprek geven ze haar als dank een duur horloge. Monique vindt het lastig om het cadeau te weigeren. Wat is de beste handelwijze?", [["Het giftenbeleid van het kantoor volgen en zo'n kostbare gift in de regel weigeren of melden", "Een kostbare gift kan de onafhankelijkheid van de adviseur aantasten of die schijn wekken. Het giftenbeleid bepaalt wat mag; een duur horloge wordt meestal geweigerd of gemeld."], ["Het horloge aannemen, want giften van klanten zijn een privézaak van de adviseur", "Giften raken de integriteit van het kantoor en vallen onder het giftenbeleid."], ["Het horloge aannemen en het echtpaar bij een volgend advies korting geven", "Dat koppelt de gift aan een tegenprestatie en maakt het belangenconflict groter."], ["Het horloge verkopen en de opbrengst stilletjes aan de kantoorkas toevoegen", "Dit is niet transparant en lost het integriteitsprobleem niet op."]], "4a.4"],
["Binnen welke termijn moet een consument zijn klacht in de regel bij Kifid indienen nadat de financiële dienstverlener een definitief standpunt heeft ingenomen?", [["Binnen drie maanden", "Kifid hanteert als hoofdregel een termijn van drie maanden na het definitieve standpunt van de dienstverlener."], ["Binnen veertien dagen", "Zo'n korte termijn kent Kifid niet; veertien dagen is de termijn van het herroepingsrecht bij overeenkomsten op afstand."], ["Binnen vijf jaar", "Vijf jaar is de verjaringstermijn voor een vordering, niet de termijn voor een klacht bij Kifid."], ["Er geldt geen termijn", "Kifid hanteert wel termijnen, zodat geschillen tijdig worden behandeld."]], "1f.5"],
["Wat houdt het in als partijen bij Kifid kiezen voor een bindend advies?", [["Beide partijen zijn aan de uitspraak gebonden; de rechter toetst die slechts zeer beperkt", "Bij bindend advies leggen partijen zich vooraf neer bij de uitspraak; vernietiging door de rechter is alleen in uitzonderlijke gevallen mogelijk."], ["Alleen de consument is gebonden; de dienstverlener mag de uitspraak zonder gevolgen naast zich neerleggen", "Bij bindend advies zijn juist beide partijen gebonden."], ["De uitspraak is een vrijblijvend advies dat partijen al dan niet kunnen opvolgen", "Dat beschrijft een niet-bindend advies."], ["De AFM zorgt voor de uitvoering van de uitspraak door een boete op te leggen", "De AFM speelt geen rol bij het ten uitvoer leggen van Kifid-uitspraken."]], "1f.21"],
["Eva Janssen (33) koopt haar eerste appartement. Ze leent € 250.000,00 bij een bank. Bij de notaris tekent ze de hypotheekakte, waarmee de bank een recht van hypotheek op het appartement krijgt. Eva vraagt zich af wie in deze akte de hypotheekgever is. Wat is juist?", [["Eva is de hypotheekgever en de bank is de hypotheeknemer", "Eva geeft het recht van hypotheek op haar appartement aan de bank. De bank neemt dat recht als zekerheid en is dus hypotheeknemer."], ["De bank is de hypotheekgever, omdat zij het geld geeft", "Het gaat om het recht van hypotheek, niet om het geld: dat recht geeft Eva aan de bank."], ["De notaris is de hypotheekgever, omdat hij de akte opmaakt", "De notaris is geen partij bij het recht van hypotheek; hij legt het vast."], ["Eva en de bank zijn allebei hypotheeknemer", "Er is één hypotheekgever, Eva, en één hypotheeknemer, de bank."]], "1c.9"],
["Jesse (29) en Mila (28) hebben een bod van € 400.000,00 gedaan op een tussenwoning, en dat bod is geaccepteerd. Volgens het taxatierapport is de marktwaarde van de woning € 380.000,00. Ze willen het volledige aankoopbedrag lenen. Hun inkomen is ruim voldoende. Wat is het gevolg van de lagere taxatiewaarde?", [["Zij kunnen in beginsel maximaal de marktwaarde lenen en betalen het verschil zelf", "De geldverstrekker baseert de maximale lening op de getaxeerde marktwaarde, niet op de koopsom. Het bedrag daarboven, plus de kosten koper, brengen zij zelf in."], ["De taxatiewaarde speelt geen rol, omdat de bank uitgaat van de koopsom", "De lening wordt juist gerelateerd aan de getaxeerde marktwaarde."], ["Zij kunnen meer lenen, omdat hun inkomen ruim voldoende is", "Naast het inkomen is ook de waarde van de woning een grens voor de hypotheek."], ["De verkoper moet de koopsom verlagen tot de getaxeerde marktwaarde", "De koopovereenkomst blijft gelden; de taxatie verandert de koopsom niet."]], "1c.15"],
["Wat is voor een consument een belangrijk voordeel van Kifid ten opzichte van een procedure bij de rechter?", [["Kifid is laagdrempelig, goedkoper en deskundig op financieel gebied", "Daardoor kan een consument zonder hoge kosten of advocaat een geschil laten beoordelen."], ["Kifid kan de dienstverlener strafrechtelijk laten veroordelen", "Kifid is een geschilleninstantie en heeft geen strafrechtelijke bevoegdheden."], ["Een uitspraak van Kifid is altijd bindend voor beide partijen", "Of een uitspraak bindend is, hangt af van de keuze van partijen."], ["Bij Kifid hoeft de klacht niet eerst bij de dienstverlener te worden gemeld", "Ook voor Kifid moet de consument zijn klacht eerst aan de dienstverlener voorleggen."]], "1f.5"],
["Wat zijn de drie klassieke fasen van witwassen?", [["Plaatsing, versluiering en integratie", "Crimineel geld wordt in het financiële stelsel gebracht, de herkomst wordt verhuld en het geld keert schijnbaar legaal terug in de economie."], ["Identificatie, verificatie en melding", "Dat zijn stappen die een instelling zet bij cliëntenonderzoek en melden, geen fasen van witwassen."], ["Verwerving, besteding en belegging", "Dit zijn geen erkende fasen van het witwasproces."], ["Ontvangst, overboeking en terugbetaling", "Dit beschrijft betalingsverkeer, niet de fasen waarin geld wordt witgewassen."]], "4a.3"],
["Wat houdt de risicogebaseerde benadering onder de Wwft in?", [["De zwaarte van het cliëntenonderzoek wordt afgestemd op het risico", "Het risico van cliënt, product, transactie en land bepaalt hoe diepgaand het onderzoek moet zijn."], ["Alleen klanten met een hoog inkomen hoeven te worden onderzocht", "Inkomen is geen maatstaf; het gaat om het risico op witwassen of terrorismefinanciering."], ["Alle klanten krijgen precies hetzelfde onderzoek, ongeacht hun profiel", "De Wwft vraagt juist maatwerk naar risico: lichter waar dat kan, zwaarder waar het moet."], ["De klant bepaalt zelf welk risicoprofiel bij hem past", "De instelling maakt zelf de risicobeoordeling."]], "2b.1"],
["Een vaste klant met een eenvoudig, laag risicoprofiel komt voor een nieuw product. Wanneer mag een instelling volstaan met vereenvoudigd cliëntenonderzoek?", [["Als uit haar risicobeoordeling blijkt dat het risico op witwassen aantoonbaar laag is", "Vereenvoudigd onderzoek mag alleen op basis van een onderbouwde risicobeoordeling; doorlopende controle blijft nodig."], ["Altijd zodra iemand al langer dan een jaar klant is en nooit eerder problemen heeft gegeven", "De duur van de relatie bepaalt het risico niet."], ["Als de klant schriftelijk verklaart dat zijn geld legaal verdiend is", "Een eigen verklaring van de klant vervangt geen risicobeoordeling."], ["Als de adviseur het druk heeft en het onderzoek later inhaalt", "Werkdruk is geen grond om het onderzoek te beperken."]], "2b.1"],
["Wanneer is volgens de Wwft sprake van een subjectieve indicator voor een ongebruikelijke transactie?", [["Als de instelling aanleiding heeft te vermoeden dat de transactie met witwassen of terrorismefinanciering verband houdt", "Bij een subjectieve indicator is het oordeel van de instelling op basis van de omstandigheden bepalend."], ["Als de transactie boven een bij regeling vastgesteld bedrag uitkomt, ongeacht alle verdere omstandigheden van het geval", "Dat is een objectieve indicator: de melding volgt dan uit een vast criterium."], ["Als de adviseur de klant persoonlijk niet sympathiek vindt en daarom aan zijn verhaal twijfelt", "Persoonlijke gevoelens zijn geen grond; het gaat om aanwijzingen voor witwassen of terrorismefinanciering."], ["Als de AFM de transactie vooraf als verdacht heeft aangemerkt", "De AFM beoordeelt transacties niet vooraf; de instelling beoordeelt zelf."]], "3b.2"],
["Een bemiddelaar merkt dat een transactie van een klant ongebruikelijk is. Wanneer moet hij die melden bij FIU-Nederland?", [["Onverwijld nadat het ongebruikelijke karakter bekend is geworden", "De Wwft vraagt om een snelle melding, zodat FIU-Nederland tijdig kan analyseren."], ["Binnen een jaar na afloop van het boekjaar waarin de transactie plaatsvond", "Zo'n lange termijn zou de meldplicht zinloos maken."], ["Pas als vaststaat dat het werkelijk om witwassen gaat", "Zekerheid is niet nodig; een ongebruikelijke transactie wordt gemeld, de analyse doet FIU."], ["Alleen als de klant met de melding instemt", "Instemming is niet nodig; de klant mag zelfs niet over de melding worden ingelicht."]], "3b.2"],
["Wie houdt toezicht op de naleving van de Wwft door een bemiddelaar in levensverzekeringen?", [["De AFM", "De AFM is voor financiële dienstverleners zoals bemiddelaars in levensverzekeringen de Wwft-toezichthouder."], ["FIU-Nederland", "FIU-Nederland ontvangt en analyseert meldingen, maar houdt geen toezicht op naleving."], ["Het Openbaar Ministerie", "Het OM vervolgt strafbare feiten, maar is geen toezichthouder op de Wwft."], ["De Belastingdienst", "De Belastingdienst houdt Wwft-toezicht op andere groepen, zoals bepaalde handelaren, niet op financiële bemiddelaars."]], "1f.20"],
["Wie is in de regel een UBO (uiteindelijk belanghebbende) van een bv?", [["Een natuurlijk persoon met meer dan 25% van de aandelen of stemrechten, of anderszins feitelijke zeggenschap", "De UBO is de mens achter de rechtspersoon die uiteindelijk eigenaar is of zeggenschap heeft."], ["Iedere statutair bestuurder van de bv, ongeacht of hij aandelen bezit of op een andere manier zeggenschap heeft", "Een bestuurder geldt alleen als pseudo-UBO wanneer geen echte UBO kan worden vastgesteld."], ["De bank waar de bv haar zakelijke rekening aanhoudt en waar het vermogen staat", "Een bank die een rekening beheert is geen eigenaar of zeggenschapshouder."], ["Iedere werknemer van de bv die deelneemt aan een regeling voor aandelenopties", "Deelname aan een optieregeling geeft niet automatisch meer dan 25% belang of zeggenschap."]], "1b.3"],
["Bas Verhoef (42) komt op kantoor voor een levensverzekering met een koopsom. Als je om zijn identiteitsbewijs vraagt, laat hij zijn bankpas zien en een paspoort dat een jaar geleden is verlopen. Zijn nieuwe paspoort is volgens hem nog niet klaar. In zijn portemonnee heeft hij ook een geldig Nederlands rijbewijs. Wat is juist?", [["De bankpas en het verlopen paspoort zijn onvoldoende; zijn geldige rijbewijs kan wel worden gebruikt", "Voor identificatie is een geldig document nodig, zoals een paspoort, identiteitskaart of Nederlands rijbewijs. Een bankpas en een verlopen paspoort voldoen daar niet aan."], ["Het verlopen paspoort is voldoende, omdat de persoonsgegevens niet zijn veranderd", "Een verlopen document is geen geldig identiteitsbewijs."], ["De bankpas is voldoende, omdat de bank Bas al heeft geïdentificeerd", "Een bankpas is geen identiteitsdocument; het kantoor moet zelf identificeren."], ["Identificatie is alleen nodig als Bas de koopsom contant wil betalen", "Het cliëntenonderzoek is nodig bij het aangaan van de relatie, ongeacht de betaalwijze."]], "1a.9"],
["Wat houdt de Sanctiewet in de kern in voor een financiële onderneming?", [["Zij mag geen middelen of diensten verlenen aan personen en organisaties op sanctielijsten", "Daarom controleert de onderneming haar klanten op sanctielijsten en bevriest zij zo nodig tegoeden."], ["Zij moet elke klant met een betalingsachterstand melden bij de AFM", "Betalingsachterstanden hebben niets met de Sanctiewet te maken."], ["Zij moet ongebruikelijke transacties melden bij Kifid", "Ongebruikelijke transacties worden onder de Wwft bij FIU-Nederland gemeld; Kifid behandelt geschillen."], ["Zij mag zelf financiële sancties opleggen aan klanten die hun premie herhaaldelijk niet op tijd betalen", "De Sanctiewet gaat over internationale sanctiemaatregelen, niet over sancties tegen klanten."]], "4a.3"],
["Frank Mol wil als nieuwe klant een koopsom van € 40.000,00 betalen voor een lijfrenteverzekering. Hij wil het grootste deel contant afleveren op kantoor. Op de vraag waar het geld vandaan komt, zegt hij alleen dat het gespaard is. Volgens zijn eigen opgave heeft hij een bescheiden inkomen. Wat moet de Wwft-plichtige bemiddelaar doen?", [["Doorvragen naar de herkomst en de transactie bij FIU-Nederland melden als zij ongebruikelijk blijft", "Een grote contante betaling zonder aannemelijke herkomst is een sterk signaal. Blijft de transactie ongebruikelijk, dan meldt de bemiddelaar haar bij FIU-Nederland."], ["De transactie uitvoeren, want contant geld is een wettig betaalmiddel", "Dat contant geld wettig is, neemt de plicht tot melden van ongebruikelijke transacties niet weg."], ["Frank waarschuwen dat hij zal worden gemeld, zodat hij een verklaring kan voorbereiden", "Het is verboden de klant te laten weten dat er een melding wordt gedaan."], ["Frank doorsturen naar een andere bemiddelaar en verder niets ondernemen", "Doorverwijzen ontslaat de bemiddelaar niet van zijn meldplicht."]], "3b.2"],
["Wie houdt in Nederland toezicht op de naleving van de AVG?", [["De Autoriteit Persoonsgegevens", "De AP is de Nederlandse privacytoezichthouder en kan onder meer boetes opleggen."], ["De Autoriteit Financiële Markten", "De AFM houdt gedragstoezicht op de financiële markten, niet op privacyregels."], ["De Autoriteit Consument & Markt", "De ACM ziet toe op mededinging en algemeen consumentenrecht, niet op de AVG."], ["Het Klachteninstituut Financiële Dienstverlening", "Kifid beslecht financiële geschillen en is geen toezichthouder."]], "1f.39"],
["Een advieskantoor vraagt bij elke offerteaanvraag voor een autoverzekering ook naar de religie en het medisch verleden van de klant. Welk AVG-beginsel wordt hier vooral geschonden?", [["Dataminimalisatie", "Er mogen niet meer persoonsgegevens worden verwerkt dan nodig is voor het doel; deze gegevens zijn voor een autoverzekering niet nodig."], ["Juistheid", "Het probleem is niet dat de gegevens onjuist zijn, maar dat ze niet nodig zijn."], ["Recht op dataportabiliteit", "Dat is een recht van de betrokkene om gegevens mee te nemen, geen beginsel dat hier wordt geschonden."], ["Integriteit en vertrouwelijkheid", "Dat beginsel gaat over beveiliging; hier draait het om het verzamelen van overbodige gegevens."]], "1f.40"],
["Hoe lang mag een advieskantoor persoonsgegevens van klanten onder de AVG bewaren?", [["Niet langer dan nodig voor het doel, tenzij een wettelijke bewaarplicht geldt", "De AVG kent geen vaste termijn; de onderneming bepaalt die op basis van doel en wettelijke plichten."], ["Onbeperkt, zolang de gegevens maar goed beveiligd zijn tegen inbraak en verlies", "Goede beveiliging rechtvaardigt niet dat gegevens langer worden bewaard dan nodig."], ["Altijd precies zeven jaar, voor alle soorten persoonsgegevens en ongeacht het doel", "De fiscale bewaarplicht van zeven jaar geldt voor de administratie, niet als algemene AVG-termijn."], ["Hooguit één maand nadat het advies is afgerond", "Zo'n vaste korte termijn bestaat niet en zou botsen met wettelijke bewaarplichten."]], "4a.5"],
["Aan welke voorwaarden moet toestemming onder de AVG voldoen om geldig te zijn?", [["Vrij, specifiek, geïnformeerd en ondubbelzinnig gegeven, en altijd in te trekken", "Alleen dan kan toestemming dienen als grondslag voor de verwerking."], ["Mondeling gegeven aan een medewerker en daarna niet meer in te trekken", "Toestemming moet aantoonbaar zijn en kan altijd worden ingetrokken."], ["Afgeleid uit het feit dat de klant een vooraf aangevinkt vakje niet heeft uitgezet", "Vooraf aangevinkte vakjes leveren geen ondubbelzinnige toestemming op."], ["Als voorwaarde gesteld voor elke dienst, ook als de gegevens niet nodig zijn", "Toestemming afdwingen voor niet-noodzakelijke gegevens is niet vrij gegeven."]], "1f.40"],
["Een oud-klant vraagt het kantoor al zijn gegevens te verwijderen. Twee jaar geleden is zijn klantrelatie beëindigd; het kantoor deed destijds cliëntenonderzoek onder de Wwft. Wat is juist?", [["Het kantoor verwijdert wat niet meer nodig is, maar bewaart wat onder een wettelijke bewaarplicht valt", "Het recht op verwijdering wijkt voor een wettelijke bewaarplicht, zoals de Wwft-termijn van vijf jaar na het einde van de relatie."], ["Het kantoor moet direct alles verwijderen, ook de gegevens uit het cliëntenonderzoek", "Gegevens waarvoor een wettelijke bewaarplicht geldt, mogen niet eerder worden vernietigd."], ["Het kantoor mag het verzoek negeren, omdat een oud-klant geen AVG-rechten meer heeft", "Ook oud-klanten zijn betrokkenen met rechten onder de AVG."], ["Het kantoor moet eerst toestemming van de AFM vragen voordat het gegevens van een oud-klant mag verwijderen", "Voor het afhandelen van een verwijderverzoek is geen toestemming van de AFM nodig."]], "1f.39"],
["Wat wordt verstaan onder de woonquote?", [["Het deel van het inkomen dat een huishouden aan woonlasten besteedt", "De woonquote drukt de woonlasten, zoals huur of hypotheeklasten, uit als percentage van het inkomen."], ["De verhouding tussen de hypotheek en de marktwaarde van de woning", "Dat is de verhouding lening-waarde, niet de woonquote."], ["Het aantal jaren dat nodig is om een hypotheek volledig af te lossen", "Dat is de looptijd van de lening."], ["Het percentage van de WOZ-waarde dat bij het inkomen wordt opgeteld", "Dat lijkt op het eigenwoningforfait, dat met de woonquote niets te maken heeft."]], "1c.19"],
["Mark (31) en Sophie (29) kopen een woning onder de kostengrens van de Nationale Hypotheek Garantie. Hun adviseur raadt aan de hypotheek met NHG af te sluiten. Mark vraagt wat NHG precies voor hen doet. Sophie vraagt waarom de bank dan een lagere rente rekent. Wat is de kern van NHG?", [["Een borgtocht voor de lening; bij gedwongen verkoop buiten hun schuld kan een restschuld worden kwijtgescholden", "Met NHG loopt de geldverstrekker minder risico en geeft hij daarom vaak een rentekorting. Moeten Mark en Sophie buiten hun schuld de woning met verlies verkopen, dan kan de restschuld worden kwijtgescholden."], ["De overheid neemt hun maandlasten over zolang een van hen werkloos of arbeidsongeschikt is", "NHG neemt geen maandlasten over; wel kan er hulp zijn bij betalingsproblemen."], ["Ze krijgen altijd een hypotheek, ook als hun inkomen eigenlijk onvoldoende is voor de lening", "Ook met NHG gelden de normale leennormen voor inkomen en woningwaarde."], ["De woning is daarmee verzekerd tegen brand en stormschade", "Dat regelt een opstalverzekering, niet NHG."]], "1c.20"],
["Wat is de rol van de notaris bij de aankoop van een woning met een hypotheek?", [["Hij maakt de transport- en hypotheekakte op, laat ze inschrijven in het Kadaster en wikkelt de betalingen af", "De notaris zorgt dat de eigendom rechtsgeldig overgaat en het recht van hypotheek ontstaat door inschrijving in de openbare registers. Het geld loopt via zijn derdengeldenrekening."], ["Hij adviseert de koper welke hypotheek en welke geldverstrekker het beste bij hem passen", "Hypotheekadvies is de taak van een adviseur; de notaris is onpartijdig."], ["Hij taxeert de woning en stelt de marktwaarde vast voor de geldverstrekker", "Dat doet een taxateur, niet de notaris."], ["Hij beoordeelt namens de geldverstrekker of de koper de maandlasten van de lening kan dragen", "De kredietwaardigheid beoordeelt de geldverstrekker zelf."]], "1c.21"],
["Iris (40) en Bart (42) sluiten een nieuwe hypotheek af. Ze kunnen kiezen uit een rentevaste periode van 5, 10 of 20 jaar. Iris wil zo lang mogelijk zekerheid over de maandlasten. Bart wil een zo laag mogelijke rente. Wat is in de regel juist, uitgaande van een normale rentestructuur?", [["Een langere rentevaste periode geeft meer zekerheid, maar heeft meestal een hogere rente", "Bij een normale rentestructuur vraagt de geldverstrekker voor een langere rentevaste periode een hogere rente, omdat hij het renterisico langer draagt."], ["Een langere rentevaste periode geeft meer zekerheid en heeft ook altijd de laagste rente", "Bij een normale rentestructuur is de rente voor een langere periode juist hoger."], ["De lengte van de rentevaste periode heeft geen invloed op de hoogte van de rente", "De rente verschilt juist per rentevaste periode."], ["Een kortere rentevaste periode geeft meer zekerheid, omdat de rente vaker wordt aangepast", "Vaker aanpassen betekent juist minder zekerheid over de toekomstige maandlasten."]], "1c.26"],
["Peter Groen (56) ontvangt via zijn tussenpersoon de jaarnota van zijn woonhuisverzekering. Op de nota staan de premie, poliskosten en assurantiebelasting. Hij vraagt waarom hij over een verzekering belasting betaalt en waarover die wordt berekend. Hij denkt dat het om btw gaat. Wat is juist?", [["Het is assurantiebelasting op de schadeverzekering, berekend over de premie inclusief de kosten", "Over de premie van de meeste schadeverzekeringen is assurantiebelasting verschuldigd. Die wordt berekend over premie en kosten samen; btw wordt over de premie niet geheven."], ["Het is btw, die over alle diensten van de tussenpersoon wordt berekend", "Over verzekeringspremies wordt geen btw geheven, maar assurantiebelasting."], ["Assurantiebelasting wordt alleen over de poliskosten berekend, niet over de premie", "De belasting wordt over de premie en de kosten samen berekend."], ["Assurantiebelasting is een vrijwillige bijdrage die hij mag weigeren", "Het is een wettelijke belasting die de verzekeraar int en afdraagt."]], "1d.11"],
["Wat valt onder de Wft-norm van een integere bedrijfsvoering?", [["Het voorkomen van belangenverstrengeling, strafbare feiten en gedrag dat het vertrouwen schaadt", "Een integere bedrijfsvoering beschermt het vertrouwen in de onderneming en in de financiële markten."], ["Alleen het tijdig deponeren van de jaarrekening en het bestuursverslag bij de Kamer van Koophandel", "Dat is een vennootschapsrechtelijke plicht, geen invulling van de integriteitsnorm."], ["Het zo hoog mogelijk maken van de winst voor de aandeelhouders", "Winstmaximalisatie is geen integriteitsnorm en kan daar zelfs mee botsen."], ["Uitsluitend het naleven van de privacyregels uit de AVG", "Privacy is één onderdeel; de integriteitsnorm is veel breder."]], "1f.33"],
["Wat is het doel van een interne meldregeling voor vermoedens van misstanden, ook wel klokkenluidersregeling genoemd?", [["Medewerkers kunnen veilig misstanden melden zonder daardoor te worden benadeeld", "Zo komen misstanden eerder aan het licht en worden melders beschermd."], ["Klanten kunnen een klacht indienen over de kwaliteit van de dienstverlening van het kantoor", "Daarvoor dient de interne klachtenprocedure."], ["De werkgever kan het privégebruik van internet door medewerkers controleren", "Een meldregeling is geen controle-instrument van de werkgever."], ["Medewerkers melden ongebruikelijke transacties van klanten aan FIU-Nederland", "Dat is de meldplicht uit de Wwft, iets anders dan een klokkenluidersregeling."]], "4a.3"],
["Bij een advieskantoor ontdekt de boekhouder dat medewerker Erwin premies van klanten naar zijn eigen rekening heeft laten overmaken. Het gaat om tientallen klanten en ruim € 25.000,00. De eigenaar wil reputatieschade voorkomen. Hij overweegt de zaak stil te houden en Erwin alleen te ontslaan. Wat moet het kantoor in elk geval doen?", [["Verdere schade voorkomen, de gedupeerden helpen en het incident melden bij de AFM", "Fraude door een medewerker is een incident dat de financiële onderneming bij de toezichthouder meldt. Daarnaast moeten de klanten worden geholpen, bijvoorbeeld door hun dekking te herstellen."], ["De zaak intern afhandelen om reputatieschade voor het kantoor te voorkomen", "Stilhouden laat de gedupeerden in de kou staan en schendt de meldplicht."], ["Volstaan met het ontslag van Erwin, omdat het probleem dan is opgelost", "Ontslag herstelt de schade van de klanten niet en vervangt de melding niet."], ["Afwachten of de gedupeerde klanten een klacht indienen bij Kifid", "Het kantoor moet zelf actie ondernemen; de klanten weten mogelijk niet eens dat zij gedupeerd zijn."]], "4a.3"],
["Welke wettelijke regeling vergoedt langdurige zorg, zoals verblijf in een verpleeghuis vanwege dementie?", [["De Wet langdurige zorg (Wlz)", "De Wlz is een volksverzekering voor mensen die blijvend 24 uur per dag zorg of toezicht nodig hebben."], ["De Zorgverzekeringswet (Zvw)", "De Zvw dekt de basiszorg, zoals huisarts en ziekenhuis, maar niet langdurig verblijf in een verpleeghuis."], ["De Wet maatschappelijke ondersteuning (Wmo)", "De Wmo regelt ondersteuning thuis door de gemeente, niet langdurig verblijf in een instelling."], ["Een aanvullende zorgverzekering", "Een aanvullende verzekering is vrijwillig en dekt geen langdurig verblijf in een verpleeghuis."]], "1d.15"],
["Waarom screent een financiële onderneming medewerkers in integriteitsgevoelige functies op betrouwbaarheid?", [["Om integriteitsrisico's zoals fraude en misbruik van klantgegevens te beperken", "Betrouwbare medewerkers zijn een voorwaarde voor een integere bedrijfsvoering."], ["Om op basis daarvan het salaris van de medewerker vast te stellen", "Screening gaat over betrouwbaarheid, niet over beloning."], ["Omdat een goede screening de vakbekwaamheidseisen vervangt", "Betrouwbaarheid en vakbekwaamheid zijn aparte eisen."], ["Om de medewerker bij twijfel over zijn achtergrond te kunnen melden bij FIU-Nederland", "FIU-meldingen gaan over ongebruikelijke transacties, niet over sollicitanten."]], "1f.33"],
["Wat is het verschil tussen nominale en reële rente?", [["De reële rente is de nominale rente gecorrigeerd voor inflatie", "De reële rente laat zien hoeveel de koopkracht van het vermogen werkelijk groeit."], ["De nominale rente is de rente na belasting, de reële rente die vóór belasting", "Het verschil gaat over inflatie, niet over belastingheffing."], ["De reële rente is de rente die de bank in rekening brengt inclusief afsluitkosten", "Kosten meenemen geeft een effectief kostenpercentage, geen reële rente."], ["Er is geen verschil; het zijn twee namen voor hetzelfde begrip", "De begrippen verschillen juist door de correctie voor inflatie."]], "1b.15"],
["Een lening heeft een rente van 1% per maand. De rente wordt elke maand over de openstaande schuld inclusief bijgeschreven rente berekend. Wat is juist over de effectieve jaarrente?", [["Die is hoger dan 12%", "Doordat ook over bijgeschreven rente rente wordt berekend, is de effectieve jaarrente ongeveer 12,68% (1,01 tot de macht 12, min 1)."], ["Die is precies gelijk aan 12%", "12% is de som van twaalf maandrentes; het rente-op-rente-effect is dan buiten beschouwing gelaten."], ["Die is lager dan 12%", "Rente over rente maakt de jaarrente hoger, niet lager."], ["Die is gewoon 1%", "1% is de maandrente; over een heel jaar is de rente veel hoger."]], "2a.1"],
["Wat is het verschil tussen een aandeel en een obligatie?", [["Een aandeelhouder is mede-eigenaar, een obligatiehouder is schuldeiser", "De obligatiehouder heeft recht op rente en aflossing; de aandeelhouder deelt in winst en risico."], ["Een obligatiehouder is mede-eigenaar; een aandeelhouder is schuldeiser van de onderneming", "Dit is precies omgekeerd."], ["Een aandeel geeft altijd een vaste jaarlijkse rente, een obligatie nooit", "Een vaste rente is kenmerkend voor de obligatie; dividend op aandelen is niet zeker."], ["Beide geven stemrecht op de algemene vergadering van aandeelhouders", "Stemrecht hoort bij aandelen, niet bij obligaties."]], "1b.17"],
["Wat gebeurt er doorgaans met de koers van bestaande obligaties met een vaste rente als de marktrente stijgt?", [["De koers daalt", "Nieuwe obligaties bieden dan meer rente, waardoor bestaande obligaties met een lagere rente minder waard worden."], ["De koers stijgt", "Een stijgende marktrente maakt bestaande obligaties met een lagere rente juist minder aantrekkelijk."], ["De koers blijft gelijk, omdat de rente vastligt", "De vaste couponrente verandert niet, maar de marktwaarde van de obligatie wel."], ["De obligatie wordt automatisch vervroegd afgelost", "Een renteverandering leidt niet automatisch tot vervroegde aflossing."]], "1b.19"],
["Welk risico kan een belegger door spreiding over veel verschillende beleggingen vooral verminderen?", [["Het specifieke risico van afzonderlijke ondernemingen", "Tegenvallers bij één onderneming wegen minder zwaar als het vermogen over veel beleggingen is verdeeld."], ["Het marktrisico van de aandelenmarkt als geheel, bijvoorbeeld bij een crisis", "Spreiding binnen dezelfde markt neemt het marktrisico niet weg; als de hele markt daalt, daalt de portefeuille mee."], ["Het inflatierisico, dat daardoor volledig verdwijnt", "Spreiding beschermt niet volledig tegen waardevermindering door inflatie."], ["Ieder risico, zodat verlies onmogelijk wordt", "Spreiding verkleint risico's, maar sluit verlies nooit uit."]], "1b.18"],
["Ruud werkt in de bouw en neemt verplicht deel aan het pensioenfonds van zijn bedrijfstak. Zijn vrouw werkt bij een groot chemieconcern met een eigen pensioenfonds. Welke omschrijving past bij het pensioenfonds van Ruud?", [["Een bedrijfstakpensioenfonds, waarbij deelname voor de hele bedrijfstak verplicht kan zijn gesteld", "Een bpf voert de pensioenregeling uit voor een hele bedrijfstak. De overheid kan deelname verplicht stellen voor alle werkgevers in die sector."], ["Een ondernemingspensioenfonds, dat voor één onderneming of groep werkt", "Dat past bij het fonds van zijn vrouw, niet bij een fonds voor de hele bouwsector."], ["Een algemeen pensioenfonds, dat alleen voor zelfstandigen bedoeld is", "Een apf voert regelingen uit voor meerdere, niet-verbonden werkgevers, niet alleen voor zelfstandigen."], ["Een premiepensioeninstelling, die alleen lijfrenten van particuliere spaarders beheert en uitkeert", "Een ppi voert premieregelingen voor werkgevers uit, geen lijfrenten van particulieren."]], "1d.19"],
["Iemand ontvangt over precies één jaar € 1.100,00. De rekenrente is 10% per jaar. Wat is de contante waarde van dat bedrag vandaag?", [["€ 1.000,00", "Contante waarde = 1.100 gedeeld door 1,10 = € 1.000,00."], ["€ 990,00", "Hier is ten onrechte 10% van € 1.100,00 afgetrokken; contant maken is delen door 1,10."], ["€ 1.100,00", "Geld dat pas later wordt ontvangen, is vandaag minder waard."], ["€ 1.210,00", "Dat is een eindwaarde na twee jaar rente op € 1.000,00, geen contante waarde."]], "2a.1"],
["Wat houdt de wet van de grote aantallen in voor een verzekeraar?", [["Hoe meer vergelijkbare risico's hij verzekert, hoe beter hij het totale schadebedrag kan voorspellen", "Bij een groot aantal gelijksoortige risico's komt de werkelijke schadelast dichter bij de verwachte schadelast. Daardoor kan de verzekeraar een passende premie berekenen."], ["Hoe meer klanten hij heeft, hoe hoger de premie per klant moet zijn", "Meer vergelijkbare risico's maken de schadelast juist beter voorspelbaar, niet duurder per klant."], ["Een verzekeraar moet wettelijk een minimum aantal klanten hebben om een vergunning te krijgen", "De wet van de grote aantallen is een statistisch principe, geen vergunningseis."], ["Bij een groot aantal verzekerden worden de afzonderlijke schades steeds kleiner", "De omvang van afzonderlijke schades verandert niet; alleen de voorspelbaarheid van het totaal neemt toe."]], "1e.1"],
["Hans Mulder (60) belegt € 20.000,00 in Amerikaanse aandelen die in dollars zijn genoteerd. Na een jaar staan de koersen in dollars precies op hetzelfde niveau als bij aankoop. In die periode is de dollar wel flink gedaald ten opzichte van de euro. Hans denkt dat zijn belegging niets in waarde is veranderd. Wat is juist?", [["De waarde van zijn belegging in euro's is gedaald", "Hans krijgt voor zijn dollars minder euro's terug. Dat is het valutarisico van beleggen in een andere munt."], ["Er is niets veranderd, omdat de koersen gelijk zijn gebleven", "In dollars niet, maar Hans rekent in euro's en de dollar is minder waard geworden."], ["De waarde van zijn belegging in euro's is gestegen", "Een dalende dollar verlaagt juist de waarde in euro's."], ["Er is alleen een gevolg als Hans in de VS belastingplichtig is", "Het valutarisico staat los van zijn belastingplicht."]], "1c.13"],
["Wat is het effect van beleggen met geleend geld?", [["Winsten én verliezen worden vergroot ten opzichte van de eigen inleg", "Dit hefboomeffect kan het eigen vermogen snel doen groeien, maar ook snel doen verdwijnen."], ["Alleen eventuele winsten worden vergroot; verliezen blijven gelijk", "De hefboom werkt in beide richtingen."], ["Het risico daalt, omdat er een groter bedrag wordt belegd", "Meer beleggen met geleend geld vergroot het risico juist."], ["Er is geen risico, omdat de rente over de lening altijd aftrekbaar is", "De rente is niet altijd aftrekbaar en de lening moet hoe dan ook worden terugbetaald."]], "1b.18"],
["Wat beschermt het beleggerscompensatiestelsel?", [["Beleggers bij wie een failliete beleggingsonderneming geld of effecten niet kan teruggeven", "Het stelsel vergoedt in die situatie tot een maximumbedrag."], ["Beleggers tegen koersdalingen van de aandelen en obligaties in hun beleggingsportefeuille", "Koersverliezen zijn een normaal beleggingsrisico en worden niet gecompenseerd."], ["Spaarders tot € 100.000,00 per persoon per bank bij het faillissement van hun bank", "Dat is het depositogarantiestelsel."], ["Beleggers tegen de gevolgen van hun eigen verkeerde beleggingskeuzes", "Eigen keuzes blijven voor rekening van de belegger."]], "1b.21"],
["Wat is het verschil tussen een sommenverzekering en een schadeverzekering?", [["Een sommenverzekering keert een afgesproken bedrag uit; een schadeverzekering vergoedt de werkelijke schade", "Bij een sommenverzekering, zoals een overlijdensrisicoverzekering, speelt de omvang van de schade geen rol."], ["Een schadeverzekering keert een afgesproken bedrag uit; een sommenverzekering vergoedt de werkelijke schade", "Dit is precies omgekeerd."], ["Een sommenverzekering kan alleen door bedrijven worden gesloten, een schadeverzekering alleen door particulieren", "Beide soorten staan open voor particulieren en bedrijven."], ["Er is geen verschil; bij beide geldt het indemniteitsbeginsel zonder uitzondering", "Het indemniteitsbeginsel geldt voor schadeverzekeringen, niet voor sommenverzekeringen."]], "1g.10"],
["Voor welk soort risico ligt het afsluiten van een verzekering het meest voor de hand?", [["Een risico met een kleine kans maar met grote financiële gevolgen", "Zo'n risico kan iemand meestal niet zelf dragen; verzekeren verdeelt het over veel verzekerden."], ["Een risico met een grote kans en een kleine schade, zoals een kapotte paraplu", "Kleine schades kan iemand doorgaans beter zelf dragen; verzekeren is dan relatief duur."], ["Een risico dat vrijwel zeker optreedt, zoals normale slijtage", "Een zekere gebeurtenis is geen onzeker risico en daarom niet verzekerbaar."], ["Elk denkbaar risico, ongeacht de kans en de omvang", "Verzekeren is niet altijd zinvol; kans en omvang bepalen of het loont."]], "1d.2"],
["Wat is het verschil tussen bruto en netto rendement van een belegging?", [["Netto rendement is het rendement na aftrek van kosten en eventuele belasting", "Voor de belegger telt uiteindelijk wat er na kosten en belasting overblijft."], ["Netto rendement is het rendement vóór aftrek van kosten", "Dat is juist het bruto rendement."], ["Netto rendement is het rendement na correctie voor wisselkoersverschillen alleen", "Wisselkoersen beïnvloeden het rendement, maar bepalen niet het verschil tussen bruto en netto."], ["Bij beleggingsfondsen is er geen verschil tussen bruto en netto", "Ook beleggingsfondsen brengen kosten in rekening die het rendement verlagen."]], "1b.15"],
["Joris (19) leent de auto van zijn vader om naar een feest te rijden. Onderweg rijdt hij een fietser aan, die gewond raakt en een kapotte fiets heeft. De vader heeft voor de auto een WA-verzekering. De fietser vraagt hoe zij haar schade vergoed krijgt. Wat is juist volgens de WAM?", [["De fietser kan haar schade rechtstreeks bij de WA-verzekeraar van de auto claimen", "De WAM verplicht het verzekeren van de aansprakelijkheid voor motorrijtuigen, om slachtoffers te beschermen. Een benadeelde heeft een eigen recht tegen de verzekeraar, ook als een ander dan de verzekeringnemer reed."], ["De fietser moet haar schade bij haar eigen inboedelverzekering melden", "Een inboedelverzekering dekt deze schade niet; de WA-verzekering van de auto is voor de schade van slachtoffers bedoeld."], ["De WA-verzekering keert niet uit, omdat Joris niet zelf de verzekeringnemer is", "De WA-dekking geldt ook voor een andere bestuurder, zoals Joris; het slachtoffer moet beschermd zijn."], ["De fietser kan alleen Joris persoonlijk aanspreken, die de schade zelf moet betalen", "Juist om slachtoffers te beschermen geeft de WAM hun een recht tegen de verzekeraar."]], "1e.10"],
["Een kantoor heeft zijn algemene voorwaarden niet vóór of bij het sluiten van de overeenkomst aan een consument ter hand gesteld. De klant wil een beding vernietigen. Wat is in beginsel juist?", [["De klant kan het beding vernietigen, omdat hij geen redelijke mogelijkheid kreeg van de voorwaarden kennis te nemen", "Wie algemene voorwaarden gebruikt, moet de wederpartij een redelijke mogelijkheid geven om ze te lezen; anders zijn bedingen vernietigbaar."], ["De klant kan niets doen, omdat de voorwaarden ooit bij de Kamer van Koophandel zijn gedeponeerd", "Deponeren alleen is in de regel onvoldoende als de voorwaarden redelijkerwijs ter hand gesteld hadden kunnen worden."], ["De klant kan niets doen, omdat hij in de offerte met een handtekening heeft verklaard dat de voorwaarden van toepassing zijn", "Een verwijzing of akkoordverklaring vervangt de plicht om de voorwaarden beschikbaar te stellen niet."], ["Alleen de AFM kan namens de klant de algemene voorwaarden laten vernietigen", "Vernietiging is een recht van de wederpartij zelf; de AFM speelt daarin geen rol."]], "1g.1"],
["Een consument heeft een schadeverzekering die na het eerste contractjaar stilzwijgend is verlengd. Hij wil overstappen. Wat geldt in beginsel?", [["Hij kan de verzekering op elk moment opzeggen met een opzegtermijn van ten hoogste één maand", "Na een stilzwijgende verlenging mag een consument een verzekering tussentijds opzeggen met een korte opzegtermijn."], ["Hij moet wachten tot het einde van het nieuwe verzekeringsjaar voordat de polis kan eindigen", "Na stilzwijgende verlenging zit een consument niet vast aan een volledig nieuw jaar."], ["Hij kan alleen tussentijds opzeggen als de verzekeraar de premie of voorwaarden wijzigt", "Een premiewijziging geeft een extra opzegrecht, maar ook zonder wijziging is opzeggen mogelijk."], ["Hij kan de verzekering niet opzeggen, omdat hij zelf voor stilzwijgende verlenging heeft gekozen", "De wet beschermt consumenten juist tegen langdurige binding door stilzwijgende verlenging."]], "1g.21"],
["Wanneer kan een overeenkomst worden vernietigd op grond van dwaling?", [["Als zij is gesloten onder een onjuiste voorstelling van zaken, bijvoorbeeld door onjuiste inlichtingen", "Dwaling geeft een vernietigingsgrond als de dwalende bij een juiste voorstelling de overeenkomst niet zo zou hebben gesloten."], ["Als een van de partijen achteraf spijt heeft van de afspraken die zij bij het sluiten van de overeenkomst heeft gemaakt", "Spijt is geen wettelijke vernietigingsgrond."], ["Als de prijs van het gekochte product kort na het sluiten van de overeenkomst sterk daalt", "Latere marktontwikkelingen vallen buiten de dwalingsregeling."], ["Als de overeenkomst alleen mondeling is gesloten en niet op papier staat", "Een mondelinge overeenkomst is in de regel gewoon geldig."]], "1g.1"],
["Het gezin De Jong heeft een conflict met de buren over een schutting op de erfgrens. Daarnaast heeft dochter Lisa (17) een geschil met een webwinkel over een kapotte laptop. Het gezin wil hulp van een jurist en, als het nodig is, van een advocaat. Ze vragen welke verzekering hen helpt hun recht te halen. Welke verzekering past het best bij deze behoefte?", [["Een gezinsrechtsbijstandverzekering", "Deze verzekering geeft juridische hulp bij geschillen van de verzekerden als particulier, bijvoorbeeld met buren of een webwinkel. Hoe ver de dekking gaat, staat in de voorwaarden."], ["Een aansprakelijkheidsverzekering voor particulieren", "Die vergoedt schade die het gezin anderen toebrengt, maar helpt niet bij het halen van hun eigen recht."], ["Een motorrijtuigenrechtsbijstandverzekering", "Die dekt alleen geschillen die verband houden met een motorrijtuig of het verkeer."], ["Een bedrijfsrechtsbijstandverzekering", "Die is bedoeld voor geschillen van een onderneming, niet van een particulier gezin."]], "1e.11"],
["Willem Dijkstra (47) is getrouwd met Saskia. Zijn beste vriend Paul wil een lening van € 15.000,00 afsluiten om een camper te kopen. De bank wil dat Willem zich persoonlijk borg stelt voor die lening. Willem wil dat doen zonder Saskia erin te betrekken. Wat geldt in beginsel?", [["Hij heeft de toestemming van Saskia nodig; zonder die toestemming kan zij de borgtocht vernietigen", "Voor een persoonlijke borgtocht is toestemming van de echtgenoot vereist. Ontbreekt die, dan kan Saskia de borgtocht vernietigen."], ["Toestemming is niet nodig, omdat iedere echtgenoot zelfstandig rechtshandelingen mag verrichten", "Voor een borgtocht maakt de wet juist een uitzondering: daarvoor is toestemming van de echtgenoot nodig."], ["Toestemming is alleen nodig als Willem en Saskia in gemeenschap van goederen zijn getrouwd", "Het toestemmingsvereiste geldt ongeacht het huwelijksgoederenregime."], ["Alleen de bank van Paul moet de borgtocht vooraf goedkeuren", "De bank beoordeelt de borg, maar dat vervangt de toestemming van de echtgenoot niet."]], "1a.7"],
["Een klant ontdekt een fout in de uitvoering van een opdracht, maar wacht twee jaar voordat hij erover klaagt. Wat kan de opdrachtnemer in beginsel tegenwerpen?", [["Dat de klant niet binnen bekwame tijd na ontdekking heeft geprotesteerd, waardoor hij zijn rechten kan verliezen", "Op grond van de klachtplicht moet de schuldeiser binnen bekwame tijd na ontdekking van het gebrek klagen."], ["Dat elke klacht op grond van de wet binnen veertien dagen na afronding van de opdracht schriftelijk moet worden ingediend", "Een vaste termijn van veertien dagen geldt niet; de maatstaf is 'binnen bekwame tijd'."], ["Dat een klacht pas na vijf jaar in behandeling mag worden genomen", "Vijf jaar is een verjaringstermijn, geen wachttijd voor klachten."], ["Niets, omdat een klant zich op elk moment zonder gevolgen kan beklagen", "De wet kent wel een klachtplicht met mogelijk verlies van rechten."]], "1f.5"],
["Jacco (35) staat sinds een paar jaar onder curatele vanwege een verslaving. Zijn zus is door de kantonrechter benoemd tot curator. Jacco komt zelf naar het kantoor en wil een levensverzekering afsluiten om later iets na te laten. Hij wil graag meteen tekenen. Wat is juist?", [["Hij is handelingsonbekwaam; zonder medewerking van de curator is de overeenkomst vernietigbaar", "Wie onder curatele staat, kan in beginsel niet zelfstandig rechtshandelingen verrichten. De adviseur moet de curator, zijn zus, erbij betrekken."], ["Hij is volledig handelingsbekwaam, want curatele gaat alleen over medische beslissingen", "Curatele beperkt juist de handelingsbekwaamheid voor rechtshandelingen."], ["Curatele heeft alleen gevolgen voor uitgaven boven een wettelijk grensbedrag", "Curatele werkt niet met een grensbedrag; ook voor deze verzekering is medewerking van de curator nodig."], ["De adviseur kan zelf als curator optreden en namens Jacco tekenen", "De curator wordt door de kantonrechter benoemd; hier is dat zijn zus."]], "1a.11"],
["Wat is het verschil tussen een volksverzekering en een werknemersverzekering?", [["Voor een volksverzekering zijn in beginsel alle ingezetenen verzekerd, voor een werknemersverzekering alleen werknemers", "Voorbeelden zijn de AOW en Anw als volksverzekering en de WW en WIA als werknemersverzekering."], ["Voor een werknemersverzekering zijn alle ingezetenen verzekerd, voor een volksverzekering alleen werknemers in loondienst", "Dit is precies omgekeerd."], ["Een volksverzekering is altijd vrijwillig, een werknemersverzekering altijd verplicht", "Ook volksverzekeringen zijn verplichte verzekeringen voor wie eronder valt."], ["Er is geen verschil; beide begrippen worden door elkaar gebruikt", "Het verschil zit in de kring van verzekerden."]], "1e.6"],
["Sevda Arslan (39) heeft een vast contract als administratief medewerker. Ze heeft een burn-out en verwacht langere tijd niet te kunnen werken. Haar partner is bang dat het gezin direct een groot deel van haar inkomen kwijtraakt. Samen vragen ze jou wie haar inkomen de komende tijd betaalt. Wat is juist?", [["Haar werkgever, die het loon ten hoogste 104 weken voor ten minste 70% doorbetaalt", "De loondoorbetalingsplicht bij ziekte ligt bij de werkgever; pas daarna kan de WIA aan de orde komen."], ["Het UWV via een uitkering op grond van de Ziektewet", "De Ziektewet is een vangnet voor zieke werknemers zonder werkgever die loon doorbetaalt; Sevda heeft een vast contract."], ["De Sociale Verzekeringsbank via een tijdelijke ziekte-uitkering", "De SVB voert volksverzekeringen uit, zoals de AOW, en betaalt geen loon bij ziekte."], ["De gemeente via een aanvullende uitkering op grond van de Participatiewet voor de duur van de ziekte", "Bijstand is een vangnet op minimumniveau, niet de regeling voor loon bij ziekte."]], "1d.9"],
["Lars (27) werkte een half jaar als werknemer bij een webwinkel. Daarvoor heeft hij een jaar gereisd en niet gewerkt. Zijn tijdelijke contract wordt niet verlengd en hij vraagt een WW-uitkering aan. Hij wil weten of hij daar recht op heeft. Aan welke wekeneis moet hij in de regel voldoen?", [["Hij moet in de 36 weken vóór zijn werkloosheid ten minste 26 weken als werknemer hebben gewerkt", "Dit is de wekeneis van de WW. Met een half jaar werk direct voor zijn werkloosheid kan Lars daaraan voldoen."], ["Hij moet in de 104 weken vóór zijn werkloosheid ten minste 52 weken bij één werkgever hebben gewerkt", "Zo'n eis bestaat niet; de wekeneis gaat over 26 van de 36 weken, ongeacht het aantal werkgevers."], ["Hij moet in vier van de vijf kalenderjaren vóór zijn werkloosheid voldoende hebben gewerkt", "Dat is de jareneis, die bepaalt of de uitkering langer duurt dan de basisduur."], ["Hij moet ten minste één volledig jaar bij dezelfde werkgever in dienst zijn geweest", "De WW stelt geen eis van een vol jaar bij één werkgever."]], "1d.7"],
["Wat bepaalt in de regel hoe lang iemand recht heeft op een WW-uitkering?", [["Zijn arbeidsverleden, tot een wettelijk maximum", "Hoe langer iemand heeft gewerkt, hoe langer de uitkering duurt, tot de maximale duur."], ["Alleen zijn leeftijd op het moment van het ontslag", "Leeftijd speelt niet rechtstreeks een rol; het arbeidsverleden is bepalend."], ["De hoogte van zijn laatstverdiende loon", "Het loon bepaalt mede de hoogte, niet de duur van de uitkering."], ["Het aantal kinderen dat bij hem thuis woont", "Gezinssamenstelling heeft geen invloed op de duur van de WW."]], "1d.9"],
["Chantal (23) werkt via een uitzendbureau bij een distributiecentrum. Na een fietsongeluk wordt zij ziek. Haar uitzendovereenkomst eindigt tijdens haar ziekte, omdat de opdracht afloopt. Zij heeft daarna geen werkgever meer die haar loon doorbetaalt. Welke regeling vormt in de regel haar vangnet?", [["De Ziektewet", "De Ziektewet is het vangnet voor zieke werknemers zonder werkgever die loon doorbetaalt, zoals uitzendkrachten van wie de overeenkomst eindigt."], ["De AOW", "De AOW is een ouderdomspensioen vanaf de AOW-leeftijd."], ["De Anw", "De Anw is een nabestaandenvoorziening."], ["De Wet arbeidsongeschiktheidsvoorziening jonggehandicapten (Wajong)", "De Wajong is voor mensen die al op jonge leeftijd arbeidsongeschikt zijn geworden, niet voor tijdelijke ziekte."]], "1d.7"],
["Wat kenmerkt de bijstand op grond van de Participatiewet?", [["Een vangnet op het sociaal minimum, uitgevoerd door de gemeente, met een toets op inkomen en vermogen", "Bijstand is bedoeld voor wie onvoldoende eigen middelen heeft en geen beroep kan doen op andere voorzieningen."], ["Een uitkering van het UWV zonder enige toets op inkomen of vermogen", "Bijstand wordt door de gemeente verstrekt en kent juist een middelentoets."], ["Een werknemersverzekering waarvoor werknemers tijdens hun werkzame leven premie betalen en rechten opbouwen", "Bijstand wordt uit algemene middelen betaald en is geen werknemersverzekering."], ["Een aanvulling die iedereen naast een hoog inkomen kan krijgen", "Bijstand is alleen voor wie onder het sociaal minimum dreigt te komen."]], "1e.6"],
["Welke instantie voert de AOW, de Anw en de kinderbijslag uit?", [["De Sociale Verzekeringsbank (SVB)", "De SVB voert de volksverzekeringen en de kinderbijslag uit."], ["Het Uitvoeringsinstituut Werknemersverzekeringen (UWV)", "Het UWV voert de werknemersverzekeringen uit, zoals de WW en de WIA."], ["Dienst Toeslagen", "Dienst Toeslagen keert toeslagen uit, zoals zorgtoeslag en huurtoeslag."], ["De gemeente", "De gemeente voert onder meer de Participatiewet uit."]], "1d.8"],
["Hoe wordt de AOW-leeftijd bepaald?", [["Die is gekoppeld aan de levensverwachting en wordt enkele jaren vooraf vastgesteld", "Zo weten mensen tijdig wanneer hun AOW ingaat."], ["Die ligt voor iedereen vast op 65 jaar", "De AOW-leeftijd van 65 jaar is losgelaten; zij beweegt mee met de levensverwachting."], ["Iedereen kiest zijn eigen AOW-leeftijd", "De AOW-leeftijd wordt wettelijk vastgesteld en kan niet zelf worden gekozen."], ["Die hangt af van het aantal jaren dat iemand in Nederland heeft gewoond of gewerkt", "Het aantal woon- of werkjaren bepaalt de hoogte van de AOW, niet de ingangsleeftijd."]], "1d.8"],
["Wat is de EU-taxonomie?", [["Een Europees classificatiesysteem voor ecologisch duurzame economische activiteiten", "De taxonomie legt vast wanneer een activiteit wezenlijk bijdraagt aan milieudoelen zonder andere doelen ernstig te schaden."], ["Een Europese belasting op de CO2-uitstoot van ondernemingen en beleggingsfondsen", "De taxonomie is geen belasting maar een indelingssysteem."], ["Een keurmerk dat de AFM toekent aan financiële producten die aantoonbaar duurzaam zijn", "De AFM kent geen duurzaamheidskeurmerk toe; de taxonomie is Europese regelgeving."], ["Een lijst van beleggingen die voor consumenten verboden zijn", "De taxonomie verbiedt niets; zij omschrijft wat als duurzaam geldt."]], "1b.17"],
["Hanneke (45) sluit een overlijdensrisicoverzekering af op het leven van haar man Gert. Zij betaalt de premie van haar eigen rekening. Als Gert overlijdt, gaat de uitkering naar Hanneke. Hun dochter vraagt wie in deze polis welke rol heeft. Wat is juist?", [["Hanneke is verzekeringnemer en begunstigde, Gert is de verzekerde", "Hanneke sluit de verzekering, betaalt de premie en ontvangt de uitkering. Het overlijdensrisico betreft Gert, dus hij is de verzekerde."], ["Gert is verzekeringnemer en verzekerde, Hanneke is alleen begunstigde", "Hanneke heeft de overeenkomst gesloten, dus zij is de verzekeringnemer."], ["Hanneke is de verzekerde, omdat zij de premie betaalt", "De verzekerde is degene op wiens leven de verzekering is gesloten: Gert."], ["Gert is de begunstigde, omdat de uitkering over zijn overlijden gaat", "Bij zijn overlijden ontvangt Gert niets; de begunstigde is Hanneke."]], "1g.5"],
["Tom koopt op zaterdag een tweedehands auto en wil er dezelfde dag mee naar huis rijden. De verzekeraar heeft zijn aanvraag nog niet beoordeeld. Zijn tussenpersoon regelt dat hij tot de beslissing van de verzekeraar toch gedekt is. Hoe heet deze dekking?", [["Een voorlopige dekking", "Een voorlopige dekking geeft tijdelijk dekking zolang de verzekeraar de aanvraag nog beoordeelt. Wordt de aanvraag afgewezen, dan eindigt de voorlopige dekking na een korte termijn."], ["Een dekkingsbevestiging", "Een dekkingsbevestiging bevestigt dat een verzekering is gesloten, bijvoorbeeld als bewijs zolang de polis er nog niet is."], ["Een respijttermijn", "Dat is een termijn waarin een premieachterstand nog kan worden betaald voordat de dekking vervalt."], ["Een premievrije voortzetting", "Dat is het voortzetten van een levensverzekering zonder verdere premiebetaling."]], "1g.6"],
["Een klant heeft een opstalverzekering. Zijn dakgoot lekt door roest, waardoor de goot zelf vervangen moet worden. Wat bepaalt de wet in beginsel over schade door een eigen gebrek van het verzekerde object?", [["Die schade wordt niet vergoed, tenzij in de polis anders is afgesproken", "Volgens de wet komt schade door een eigen gebrek niet voor vergoeding in aanmerking. Een polis kan dit anders regelen, bijvoorbeeld voor gevolgschade."], ["Die schade wordt altijd volledig vergoed, omdat het object verzekerd is", "De wet sluit schade door een eigen gebrek juist uit, tenzij anders is afgesproken."], ["Die schade wordt alleen vergoed als de klant het gebrek al kende", "Kennis van het gebrek maakt vergoeding niet waarschijnlijker."], ["Die schade wordt via de verzekeraar vergoed door de fabrikant", "De verzekeraar regelt geen schade namens de fabrikant; het eigen gebrek is wettelijk uitgesloten."]], "1g.13"],
["Wendy (38) verliest haar baan en betaalt de vervolgpremie van haar autoverzekering niet. De verzekeraar stuurt haar een aanmaning. Een paar dagen later krijgt ze een aanrijding. Ze vraagt of ze nog gedekt is en wat er gebeurt als ze niet betaalt. Wat is juist?", [["Ze is nog gedekt: schorsen mag pas als ze 14 dagen na de aanmaning niet heeft betaald", "Bij een vervolgpremie mag de dekking pas worden geschorst als betaling binnen 14 dagen na de aanmaning uitblijft. Ook bij schorsing blijft Wendy de premie verschuldigd."], ["Ze is niet gedekt, omdat de dekking vervalt zodra de premie op de vervaldag niet is betaald", "Bij een vervolgpremie is eerst een aanmaning nodig, met een termijn van 14 dagen."], ["Ze is gedekt, en als ze niet betaalt loopt de dekking gewoon door tot het einde van het jaar", "Na een aanmaning en 14 dagen zonder betaling kan de verzekeraar de dekking schorsen."], ["Ze is niet gedekt, omdat een werkloze geen autoverzekering mag hebben", "Werkloosheid heeft geen invloed op de dekking; het gaat om de premiebetaling."]], "1g.23"],
["Gerrit (58) en Joke (56) willen weten hoe hun vermogenspositie eruitziet. Hun woning is € 420.000,00 waard en hun hypotheek bedraagt € 180.000,00. Ze hebben € 35.000,00 spaargeld en een auto van € 15.000,00. Daarnaast hebben ze een doorlopend krediet met een schuld van € 10.000,00. Hoe groot is hun eigen vermogen?", [["€ 280.000,00", "De bezittingen zijn samen € 470.000,00: woning, spaargeld en auto. Na aftrek van de schulden van € 190.000,00, hypotheek en krediet, blijft € 280.000,00 over."], ["€ 290.000,00", "Hier is het doorlopend krediet van € 10.000,00 niet als schuld meegeteld."], ["€ 470.000,00", "Dit is het totaal van de bezittingen, zonder aftrek van de schulden."], ["€ 265.000,00", "Hier is de auto niet als bezitting meegeteld."]], "2b.2"],
["Sophie Meijer (36) wil maandelijks € 300,00 beleggen voor later en vraagt beleggingsadvies. Zij geeft aan dat minstens de helft van haar beleggingen duurzaam moet zijn in de zin van de SFDR. Haar adviseur Tom stelt vast dat geen enkel product in zijn aanbod daaraan voldoet. Tom wil Sophie toch graag als klant houden. Wat is juist?", [["Tom adviseert geen product als passend bij die voorkeur; Sophie kan haar voorkeur eventueel bijstellen", "Een product dat niet aan de duurzaamheidsvoorkeur voldoet, mag niet als passend bij die voorkeur worden geadviseerd. Past Sophie haar voorkeur bewust aan, dan legt Tom dat vast."], ["Tom adviseert een niet-duurzaam product zonder dit te melden, omdat de voorkeur niet bindend is", "Duurzaamheidsvoorkeuren horen bij de geschiktheidsbeoordeling en mogen niet worden genegeerd."], ["Tom omschrijft een bestaand product in zijn adviesrapport als duurzaam, zodat het toch past", "Dat is misleidend en een vorm van greenwashing."], ["Tom laat de voorkeur buiten beschouwing, omdat duurzaamheid geen onderdeel van advies hoeft te zijn", "Bij beleggingsadvies moet de adviseur juist naar duurzaamheidsvoorkeuren vragen en die meewegen."]], "1f.15"]
];
